import { HelpBody } from './helpContent';

/**
 * The help catalog in German.
 *
 * <p>A file per language: a translation pass is then reviewable on its own, and eighteen articles
 * in five languages inline would be one literal nobody could edit without breaking a quote. A key
 * that is missing here falls back to the English body, visibly — see `bodyFor`.</p>
 */
export const DE: Readonly<Record<string, HelpBody>> = {
  'security-lane': {
    title: 'Security lane: zusätzliche Sicherheitsprüfungen',
    whatItIs: 'Optionale Prüfungen neben dem regulären Code- und Feature-Review. Jedes Paar verbindet einen eingerichteten Reviewer mit einem redteam-Prompt. Standardmäßig ausgeschaltet; das reguläre Gate bleibt erforderlich.',
    why: 'Eine gezielte Prüfung untersucht eine Sicherheitsgrenze und bewahrt Befunde samt Belegen im gemeinsamen Verlauf auf.',
    setup: 'Unter Settings → Security lane die Lane einschalten. Jeder Prompt ist eine Karte: grün für einen mitgelieferten, orange, sobald Sie seinen Text oder seine Bedingungen ändern (Restore default stellt ihn wieder her), lila für einen eigenen. Einen Reviewer auf einer Karte anhaken, um ein Paar zu bilden. redteam-general steht zuerst und läuft bei jeder Codeänderung, solange ein Reviewer angehakt ist. Die übrigen mitgelieferten Module laufen, wenn geänderter Code zu ihren Bedingungen passt; die Bedingungen sind in der Karte eingeklappt, neben den bevorzugten Quellen, und ein Modul ohne Bedingung läuft nicht. Einen eigenen Prompt legt + New custom prompt an: Es fragt nach einem redteam-Namen, legt prompts/<Name>.md im Datenverzeichnis an und öffnet sie; die Karte nennt diese Datei und sagt, wenn sie keinen brauchbaren Text enthält. Edit prompt text öffnet die Datei erneut; Remove custom prompt nimmt den Prompt und seine Paare aus der Lane, die Datei bleibt auf der Festplatte. Jedes Paar hat Stufen, einen Quellmodus und ein Token-Budget; + Add reviewer / prompt pair und Remove pair sind Schaltflächen. Standard sind zwei Runden und null erlaubte major/blocking-Befunde. Mitgelieferte Prompts liegen unter src_mcp/src/prompts/redteam-*.md in Git; Edit local prompt override öffnet eine separate lokale Datei und ändert die Git-Fassung nicht.',
    usage: 'SECURE steht für eine leere Befundliste. Jeder Befund benötigt Trigger, Mechanism und Consequence. Ohne vollständige Reproduktion wird major/blocking vor dem Zusammenführen auf minor begrenzt. Belege erscheinen im Verlauf und werden niemals ausgeführt. Die bestehenden Parallelitätsgrenzen gelten weiter. Ein Paar wählt aus den Modellen, die auf Models **security lane** angehakt sind, und ein Modell kann allein für die Lane angehakt sein, ohne sonst etwas zu prüfen.',
    whatCanGoWrong: 'MCP 0.41.0 oder neuer ist erforderlich. Ältere Server erhalten die Einstellung nicht. redteam-general läuft erst ab MCP 0.43.0 nur bei Codeänderungen; ein älterer Server führt es bei jeder Änderung aus, auch bei reiner Dokumentation. Meldet seine Karte gespeicherte Bedingungen von früher, drücken Sie Clear stored conditions — bis dahin führt ein älterer Server es nur aus, wenn sie zutreffen. Fehlende Prompts, nicht verfügbare Laufzeiten und ungültige Einstellungen werden benannt. Ist coai.securityLane in Ihrem settings JSON fehlerhaft, bleibt die Lane aus; der Tab Security lane nennt den Fehler, korrigieren Sie ihn dort. Kontext ist begrenzt, Auslassungen werden genannt; die Vollständigkeit lokaler Eingaben bleibt unbestätigt. Eine erfolgreiche Zusatzprüfung ersetzt keinen ausgefallenen regulären Reviewer.',
  },
  "the-settings-tab": {
    title: "Das Panel und der Settings-Tab",
    whatItIs: "Die Seitenleiste zeigt, was gerade passiert: **Active questions** — woran der Question consultant gerade arbeitet, und eine Frage, die auf Ihre Antwort wartet —, dann **Notifications**, **Active gates** — die Runden, die in dieser Minute laufen —, **Active consultations** — die Konsultationen, die gerade geführt werden —, **Consultation cadence** — wo jeder Plan steht, dem der Takt folgt —, **Phrases** und **Bugz**. Alles, was Sie einmal einrichten, liegt im Tab **Settings**, den das Zahnrad neben der Hilfe-Schaltfläche in der Titelleiste des Panels öffnet. Er hat sechs Tabs, in dieser Reihenfolge. **Models** ist jedes Modell, das diese Seite nutzen kann, einmal angelegt, jedes eine Karte, auf der angehakt ist, wofür es verwendet wird. **Reviews** enthält das Review-Gate in sechs Unter-Tabs: **Stages** (Runden und Schwelle jeder Rolle, die Verteil-Schalter und was ein Reviewer bekommt), **Roles & prompts** (die Rollen, ihre Prompts und der eine Schalter jeder Rolle), **Prompts per round**, **The gate** (was passiert, wenn die Runden aufgebraucht sind, und die Anweisungen, die das Gate gibt), **Commands** und **Limits**. **Consultants** enthält **Consultant** und **Question consultant**. **Security lane** sind die zusätzlichen Sicherheitspaare. **Chat** ist, auf welchem Modell ein Chat öffnet, wie eine Stelle gesendet wird, und die Prompt-Vorlagen. **Setup** enthält **Vendor keys**, **Team servers**, **MCP server** und **This side**.",
    why: "Vierzehn eingeklappte Abschnitte in einer schmalen Spalte hießen: an zehn einmal eingerichteten Dingen vorbeiscrollen, um die vier zu erreichen, für die man wiederkommt. Die Tabs enthalten dieselben Bedienelemente wie die Abschnitte, mit derselben Wirkung — geändert hat sich nur, wo sie gezeichnet werden —, eine Wahl im Tab wird also genau so gespeichert wie dieselbe Wahl in der Seitenleiste. **Models steht zuerst**, weil ein Modell einmal definiert wird und jede Funktion daraus wählt: ein Reviewer, ein Konsultant, eine Zeile des Question consultant, ein Sicherheitspaar, der Chat und Bugz nennen jeweils ein Modell auf Models, statt eine Kopie seiner Einstellungen zu halten — eine Karte zu bearbeiten ändert dieses Modell also überall, wo es verwendet wird.",
    setup: "Nichts einzurichten. **ConnectOtherAIs: Settings** in der Befehlspalette öffnet denselben Tab. Es gibt einen pro Fenster: ein erneuter Klick auf das Zahnrad holt ihn zurück, statt einen zweiten zu öffnen, und er öffnet sich an dem Ort, an dem Sie in diesem Fenster zuletzt waren.\n\n**Dies ist die einzige Settings-Seite.** Die Seite, die sie ersetzt hat, ist fort, und mit ihr deren eigene Tabs für Reviewer, Rollen, Gate-Befehle und Chat-Vorlagen sowie der Schalter zwischen den beiden Seiten. Drei Befehle jener Seite — **Edit review roles**, **Edit the gate's commands** und **Edit chat presets** — bleiben noch ein Release lang in der Befehlspalette und öffnen diesen Tab bei **Reviews › Roles & prompts**, **Reviews › Commands** und **Chat**. Ein Link auf einen alten Ort öffnet den Ort, der ihn jetzt enthält.",
    usage: "Klicken Sie auf einen Tab oder nutzen Sie die Tastatur: Links und Rechts wandern die Leiste entlang und springen an den Enden auf die andere Seite, Pos1 und Ende gehen zum ersten und letzten Tab, Tab verlässt die Leiste. Ein Tab mit Unter-Tabs hat eine eigene Leiste, die genauso funktioniert, und sie öffnet sich auf dem Unter-Tab, auf dem Sie dort zuletzt waren. Jede Änderung wird sofort gespeichert, wie in der Seitenleiste, und eine neue Antwort — eine CLI-Version, eine Modellliste, ein Preis — erscheint, sobald sie eintrifft. Strg+F durchsucht den Ort, an dem Sie sind. Die beiden ±-Paare neben dem Titel ändern hier wie auf jeder anderen Seite die Textgröße und ihren Ton, und **Setup › MCP server** wird in anderthalbfacher Größe gezeichnet, weil es öfter gelesen als eingestellt wird.\n\n**Am Ort einer Funktion — Consultants, Security lane, Chat — nennt eine Zeile oben die Modelle, die für sie angehakt sind**, und **Change on Models** öffnet Models, eingegrenzt auf die Modelle, die für diese Funktion angehakt sind. **Edit roles…**, in Reviews › Stages, und **Edit commands…**, in Reviews › The gate, springen zu Reviews › Roles & prompts und Reviews › Commands.\n\n**Ein kleines ? neben einer Einstellung sagt, was sie bedeutet**, wenn Sie mit der Maus darüberfahren: was die Einstellung tut und warum es sie gibt, in einem Satz, nach dem Sie handeln können. Diese Seiten sagen dasselbe ausführlich; das ? ist für den Moment, in dem Sie auf das Bedienelement schauen.",
    whatCanGoWrong: "Das Zahnrad erscheint, solange der Mauszeiger über dem Panel ist oder es den Fokus hat, wie jede Titelleisten-Schaltfläche in VS Code; der Eintrag in der Befehlspalette ist immer da. Nach einem Neuladen des Fensters kommt der Settings-Tab nicht von selbst zurück — klicken Sie erneut auf das Zahnrad, und er öffnet sich auf **Models**, denn welcher Ort offen war, wird nur so lange behalten, wie das Fenster lebt. Eine laufende Konsultation steht in der Seitenleiste unter **Active consultations**, nicht in **Consultants › Consultant**: Die Seitenleiste zeigt, was gerade passiert, und in Consultants entscheiden Sie, wer gefragt wird.",
  },
  "phrases": {
    title: "Phrases: die Sätze, die Sie nicht mehr abtippen",
    whatItIs: "Eine Liste von Sätzen, die Sie aufbewahren — als Schaltflächen im Abschnitt **Phrases** des Panels. Eine davon drücken, und sie liegt in der Zwischenablage; eingefügt wird sie dort, wo Sie sie sonst getippt hätten, meist im Eingabefeld von Claude Code. Bearbeitet wird die Liste in einem eigenen Tab: **ConnectOtherAIs: Edit phrases**.",
    why: "Manche Anweisungen tippt man mehrmals am Tag — *mach einen Pull Request, nimm ihn an, deploye, prüf dass es läuft*. Sie erneut zu tippen ist keine Arbeit, sondern Reibung, und ein aus dem Gedächtnis wiederholter Satz verändert sich jedes Mal ein wenig.\n\n**Es wird kopiert und nicht für Sie ins Feld geschrieben, und das war eine Entscheidung, keine Abkürzung.** Claude Code hat keinen Befehl, der beliebigen Text annimmt: der eine, der einen Prompt annimmt, füllt nur eine NEUE Unterhaltung, nie die, in der Sie gerade sind. Übrig blieb ein synthetischer Tastendruck über die Windows-API — nur Windows, etwa eine Sekunde lang, und in diese Richtung nie gemessen. Ein `Ctrl+V` ist der bessere Preis als ein Mechanismus, der auf einem fremden Rechner stillschweigend scheitern kann.",
    setup: "**Edit phrases** aus dem Abschnitt *Phrases* des Panels oder aus der Befehlspalette. **Add a phrase** drücken, einen Namen für die Schaltfläche vergeben und den Satz in das große Feld schreiben. Alles wird kurz nach dem letzten Tastendruck gespeichert.\n\nDer Name ist nur eine Beschriftung; in die Zwischenablage geht der Satz selbst. Lassen Sie den Namen leer, trägt die Schaltfläche die erste Zeile des Satzes.\n\n**Eine neue Installation beginnt mit sieben Beispielsätzen** — den Sätzen, die eine Person am häufigsten in Claude Code tippt. Bearbeiten, entfernen oder eigene hinzufügen; sobald Sie eine Liste gespeichert haben, gehört sie Ihnen, und eine geleerte Liste bleibt leer.",
    usage: "Der Abschnitt **Phrases** zeigt eine Schaltfläche je Satz. Drücken, einfügen, weiterarbeiten. Die Liste gehört Ihnen allein: Sie geht nie an `coai-mcp` und wird nie auf einen Team server gespiegelt, und sie ist bei eingeschaltetem *This side* auf beiden Seiten dieselbe — ein Satz, den Sie geschrieben haben, ist keine Eigenschaft des Rechners, auf dem Sie ihn geschrieben haben.\n\nEin Satz wird genau so gespeichert, wie Sie ihn geschrieben haben, mit Leerzeichen und Zeilenumbrüchen: ein eingerückter Schnipsel wird eingerückt eingefügt, und ein abschließender Zeilenumbruch bleibt, wo Sie ihn hingesetzt haben.",
    whatCanGoWrong: "**Eine Zeile ohne Text wird verworfen.** Der Name ist die Beschriftung, der Text ist die Sache — eine Zeile ohne Inhalt ist kein Satz. Eine Zeile, die Sie in `settings.json` vertippt haben, wird für sich verworfen, und der Rest der Liste funktioniert weiter: alle Sätze wegen eines falschen zu verlieren wäre das schlimmere Versagen.\n\n**Ein Speichern, das nicht gelingt, sagt es — und sagt warum.** Der Tab behält das Getippte und zeigt den Grund der Ablehnung in den Worten dessen, der sie ausgesprochen hat, statt die Liste ohne Ihre Worte neu zu zeichnen. Der häufigste Grund ist ein Fenster, das einer Aktualisierung nicht gefolgt ist: VS Code kennt weiterhin nur die Einstellungen, die es beim Öffnen des Fensters registriert hat, ein Satz lässt sich also erst nach dem Neuladen speichern — die Zeile sagt genau das, mit der Schaltfläche dafür.\n\n**Nichts wird für Sie gedrückt.** Der Satz erreicht die Zwischenablage und hört dort auf; ihn einzufügen und abzuschicken bleibt Ihre Sache.",
  },
  "notifications": {
    title: "Notifications: alles, was die Erweiterung Ihnen gesagt hat",
    whatItIs: "Eine Seite mit allen Meldungen, die ConnectOtherAIs auf Ihrem Bildschirm gezeigt hat, aufbewahrt nachdem die Einblendung verschwunden ist: was sie sagte, wann, woher, was zu tun ist und wie oft es passiert ist. Der Abschnitt **Notifications** im Panel nennt die Zahl der neuen und öffnet sie.",
    why: "Eine Meldung, die Sie nicht angesehen haben, ist eine Meldung, die nie stattgefunden hat. Am 16.09.2026 wurde eine um 19:05 gelöschte Rolle noch elf Runden lang mitgeprüft, weil der Einstellungsspiegel um 18:27 angehalten hatte und das genau einmal sagte — in einer Einblendung, die niemand sah. Neunzig Minuten eines Arbeitstags gingen dafür drauf, das herauszufinden. Jetzt geht jede Meldung zuerst in eine Datei und erst dann auf den Bildschirm, damit die Antwort auf «was stand da?» woanders liegt als im Gedächtnis eines Menschen.",
    setup: "Nichts einzurichten. Diese Erweiterung schreibt in `notifications.jsonl`, im selben Datenordner wie alles andere. Die Seite liest daneben auch `server-notices.jsonl` — dorthin wird der MCP-Server schreiben, doch diese Hälfte ist noch nicht gebaut, sodass die Datei auf einer laufenden Installation heute schlicht fehlt. Wird der Ordner verschoben, ziehen sie mit um.",
    usage: "Der Abschnitt **Notifications** sagt, wie viel seit Ihrem letzten Blick neu ist, und öffnet die Seite. Dort ein Reiter je ART — ein Fehlschlag, eine Ablehnung, ein Anhalten, ein Sturm, eine Frage, die Sie beantwortet haben — und eine Zeile je Vorfall, so oft er auch aufgetreten ist.\n\n**Eine Zeile ist ein Fehler, kein einzelnes Auftreten.** Ging etwas vierhundertmal schief, ist das eine Zeile mit der Vierhundert und daneben, wie schnell sie eintrafen. Sortieren nach jeder Spalte; Leerwerte stehen in beiden Richtungen hinten, damit eine nicht messbare Rate nie nach oben rutscht. Die Suche findet jedes Wort der Zeile, auch die Meldung selbst. **Source** grenzt auf das ein, was ein Teil der Erweiterung gesagt hat, **From** und **To** auf eine Zeitspanne, und **Clear** nimmt alle zugleich weg. **Previous** und **Next** blättern seitenweise durch die Zeilen.\n\nDas Öffnen der Seite markiert die geladenen Einträge als gelesen. **Bei gesetztem Filter markiert sie nichts** — drei Zeilen auf dem Bildschirm dürfen nicht behaupten, dreitausend seien gelesen — und die Zeile über der Tabelle sagt, welches von beiden gerade gilt. **Mark everything read** ist die Schaltfläche für eine Historie, die Sie nicht rückwärts durchgehen wollen.",
    whatCanGoWrong: "**Ein sich wiederholender Fehler ist begrenzt und sagt das, statt so zu tun als ob.** Dieselbe Sache kann in einem Fensterlauf tausendmal festgehalten werden; danach hört die Datei auf, und die Zeile liest sich *1000+* — nie als Zahl, die niemand kennen kann. Drei Fenster, die das je erreichen, erscheinen als *1000+ in each of 3 runs*, denn drei Fenster in Not sind nicht ein dreifach so großer Vorfall.\n\n**Die Seite zeigt die neuesten paar tausend Einträge, nicht die Datei.** Gibt es ältere, sagt sie das, und die bleiben ungelesen, bis Sie hingehen oder **Mark everything read** drücken.\n\n**Eine Zählung, die nicht gelesen werden konnte, sagt das, statt null zu zeigen.** «Es wurde noch nichts aufgeschrieben», «die Benachrichtigungen konnten nicht gelesen werden» und «nichts Neues» sind absichtlich drei verschiedene Sätze: ein kaputter Lesevorgang, der als sauberes Null erscheint, bringt einen Menschen dazu, einem Zähler nicht mehr zu trauen — und dieser Zähler gibt es, weil jemandem eine Meldung entgangen ist.\n\n**Geheimnisse werden beim Hineinschreiben entfernt.** Ein Passwort, ein Token oder ein Schlüssel in einer URL oder in einem Fehlertext wird ersetzt, bevor die Zeile die Datei erreicht; alles andere bleibt erhalten. Auf einer Maschine kann es zwei Datenordner geben, einen für Windows und einen für WSL; die Seite nennt den, den sie liest, denn «er ist leer» und «Sie sehen in den anderen» sind verschiedene Probleme.",
  },
  "your-own-roles": {
    title: "Eigene Rollen: prüfen, was kein Code ist",
    whatItIs: "Eine Review-Rolle ist ein Prüfer mit einer Frage. Fünf liefert dieses Produkt mit: Plankritik, Konventionen, Architektur, Sicherheit und Zuverlässigkeit, Performance und UX-DX. **Die Rollen, die Sie hinzufügen, gehören Ihnen** — mit Namen in Ihrer Sprache und den Fragen, die Sie gestellt haben wollen.\n\nDas Gate ringsherum ändert sich nicht. Dieselben Runden, dieselbe Schwelle, dieselben Funde mit denselben Kategorien, dasselbe Urteil. Was sich ändert, ist, wonach ein Prüfer gefragt wird — und das ist der Prompt, den Sie schreiben.",
    why: "Die fünf mitgelieferten sind die fünf, die ein Programmierer will. Wer Anforderungen gegen eine Spezifikation prüft, Bewerbungen liest oder eine Produktbeschreibung vor der Veröffentlichung durchgeht, braucht eine andere Frage — und niemand kann sie alle im Voraus kennen. Deshalb ist es eine Liste, die Sie bearbeiten, und keine, die wir ausliefern.",
    setup: "Die Rollen werden in **Reviews › Roles & prompts** bearbeitet; **Edit roles…**, unter den Stufen in **Reviews › Stages**, springt dorthin. Drücken Sie **Add a role**, unter der Code-Stufe, geben Sie ihr einen Namen und schreiben Sie ihren allgemeinen Prompt — die Frage, die gestellt wird, wenn nichts anderes gewählt ist. Weitere Prompts für engere Fragen kommen dazu; in **Reviews › Prompts per round** wird pro Runde einer davon angeboten.\n\nDie fünf mitgelieferten Rollen stehen am selben Ort. Den Text jedes ihrer Prompts können Sie neu schreiben und eigene Prompts hinzufügen; umbenennen, auf die andere Stufe verschieben oder Mitgeliefertes löschen können Sie sie nicht — ihre Namen sind bereits Schlüssel in Ihren Einstellungen, in offenen Sitzungen und in jeder aufgezeichneten Runde, und der Review-Server liest nichts davon aus Ihrer Konfiguration: ein Ort, der das ändern ließe, zeigte etwas, das keine Runde je tut.\n\n**Eine Kennung wird für Sie erzeugt** und unter dem Namen angezeigt. So heißt Ihre Rolle in der Einstellung, in der Sitzungsdatei und in der Datenbank, deshalb ändert sie sich danach nicht mehr — benennen Sie die Rolle um, so oft Sie wollen.\n\n**Höchstens fünf Rollen sind pro Stufe aktiv.** Eine sechste lässt sich nicht anhaken; schalten Sie zuerst eine ab. Eine Rolle, die Sie anlegen, entsteht abgeschaltet — sie hat noch keine Frage —, und sie lässt sich nicht einschalten, solange bereits fünf aktiv sind; was Roles & prompts zeigt, ist damit das, was läuft. Eine abgeschaltete Rolle bleibt mit allem, was Sie hineingeschrieben haben, in Roles & prompts.",
    usage: "Alles in Roles & prompts speichert sich einen Moment, nachdem Sie aufgehört haben zu tippen. Der TEXT eines Prompts landet in einer Datei neben Ihren übrigen coai-Daten — genau dort hat der Server Prompt-Überschreibungen schon immer gelesen. Ein neu geschriebener Prompt übersteht daher ein Update, und das Löschen der Datei stellt das Mitgelieferte wieder her.\n\n**Eine Rolle für etwas, das keine Programmieraufgabe ist,** wird von `review_document` ausgeführt, dem Dokument-Gate, wenn ihre Stufe *Code review* ist: sie liest ein DOKUMENT statt eines Diffs, und Roles & prompts führt sie unter **Document stage**. Auf der Plan- oder der Feature-Stufe wird eine solche Rolle aufbewahrt und nimmt an keiner Runde teil — für Arbeit, die kein Programmieren ist, gibt es kein Plan-Gate, und ein Feature-Review liest Code. Roles & prompts sagt das an der Rolle.\n\n**Roles & prompts, Element für Element.** Vier Gruppen mit Überschrift — **Plan stage**, **Code stage**, **Document stage** und **Feature stage** — eine je Art von Runde, und jede Rolle steht in der, in die ihre Stufe und ihre Art sie stellen. Eine Rolle klappt auf zu ihrem **Name**, einer Auswahl **Stage** (Plan review, Code review oder Feature review), **A programming task** und **Active**. *Active* ist der EINE Schalter der Rolle: nicht angehakt, nimmt sie an keiner Runde teil, und ihr Kasten in **Reviews › Stages** sagt, wo der Schalter ist. Darunter ist jeder Prompt eine Zeile aus dreien: was die Auswahl zeigt, der Tooltip der Auswahl und der Text. Bei einem mitgelieferten Prompt stehen die ersten beiden fest, und **Restore** nimmt Ihren Text wieder weg; bei einem eigenen Prompt gehören Ihnen alle drei, und **Remove** entfernt ihn. **Add a prompt** fügt dieser Rolle einen hinzu, und **Remove this role** — nur bei einer eigenen Rolle angeboten — nimmt die Rolle weg.\n\n**Das Entfernen einer Rolle fragt vorher nach** und nimmt die Prompts mit, die Sie darin geschrieben haben: die Zeile lässt sich neu tippen, die Absätze darunter nicht.\n\n**Eine Löschung, von der der Server noch nichts weiß, steht oben in Roles & prompts**, mit dem Grund, und ihre Prompts bleiben erhalten, bis der Server sie hat. **Reload Window** wird angeboten, wenn der Grund ist, dass der Einstellungsspiegel dieses Fensters angehalten hat — ein neuerer Build besitzt die Einstellungsdatei, und durch das Neuladen wird dieses Fenster zu diesem Build. **Finish the deletion anyway** löscht die Prompts sofort und sagt, bevor Sie drücken, was das kostet: der Server kann die Rolle ohne ihren Text weiter ausführen, bis seine Einstellungen nachziehen, und Runden gegen sie beschweren sich jedes Mal.",
    whatCanGoWrong: "**Ein `coai-mcp` älter als 0.19.0 liest Ihre Rollen gar nicht.** Dieses Release hat es gelernt: darunter stehen die Rollen im Panel und in keiner Runde — nichts schlägt fehl und nichts sagt es, weshalb Roles & prompts eine Warnung mit Ihrer Version zeigt. Aktualisieren Sie den Server unter **Setup › MCP server**.\n\n**Ein Team server führt die Rollen aus, die sein Betreiber eingerichtet hat.** Er bringt dieselben fünf mit, und sein Betreiber kann weitere hinzufügen: `Coai:ExtraRoles` auf dem Server, oder `Coai:AllowAnyRole`, um jede GÜLTIGE Rollenkennung anzunehmen, gleich wer sie benannt hat. Das Panel fragt jeden eingerichteten Server, welche Rollen er ausführt, und sagt es neben der Rolle — VOR einer Runde, nicht in ihrem Ergebnis: *work runs Architecture, Conventions — not Requirements we wrote*. Ein Server, der zu alt ist, um danach gefragt zu werden, oder einer, der nicht erreichbar war, führt weiterhin die fünf mitgelieferten aus — und der Satz sagt, welcher der beiden Fälle eintrat, denn der eine wird durch ein Server-Update behoben und der andere durch einen Blick aufs Netz.\n\n**Zwei Seiten, zwei Rollensätze.** Mit *This side* gehören Ihre Rollen der Seite, auf der Sie arbeiten, wie Runden und Schwellen. Die Prompt-Dateien nicht: eine Frage, die Sie geschrieben haben, ist eine Frage, wo immer Sie sie stellen.",
  },
  "chat-with-other-ai": {
    title: "Chat with other AI: ein zweites Modell zu einer Stelle befragen",
    whatItIs: "Markieren Sie einen Absatz in der Antwort Ihres Assistenten und drücken Sie `Ctrl+Alt+A` — es öffnet sich ein Tab, in dem das Modell eines anderen Anbieters ihn in Ihrer Sprache erklärt, und das Gespräch geht weiter. Im Kontextmenü steht dasselbe als zwei Einträge, und jeder sagt, was er tut: **CoAI: default** fragt sofort das als main markierte Modell, und **CoAI: choose** legt den Zug ins Eingabefeld — Sie können Modell oder Prompt noch ändern und selbst Enter drücken. Die Tasten folgen weiterhin der Einstellung **Who presses send**, die ein Menüeintrag nicht zeigen kann.\n\nEs geht auch in einer gewöhnlichen Datei — `.md`, `.cs`, jeder, die Sie öffnen können. Markieren Sie eine Stelle und drücken Sie dieselben Tasten, oder klicken Sie mit der rechten Maustaste. Dort wird die Markierung direkt aus dem Editor gelesen statt über die Zwischenablage kopiert: sofort, und Ihre Zwischenablage bleibt unangetastet. Ohne Markierung geht die ganze Datei, und bei einer großen Datei wird vorher gefragt. Das Gespräch trägt den Namen der Datei, und eine zweite Frage zu derselben Datei führt dasselbe Gespräch fort.\n\n**CoAI: take the question** ist dasselbe für eine Frage, die Claude Code IHNEN stellt, und es steht im Kontextmenü des Claude-Code-Panels — nicht in dem eines Editors, wo es keine Frage zu übernehmen gibt. Sein Fragefenster lässt sich nicht markieren, es gibt nichts zu kopieren — also wird die Frage aus der Sitzungsdatei gelesen, mit jeder Option und jeder Beschreibung, und landet im Eingabefeld. Es lehnt ab, statt zu raten: War die letzte Frage schon beantwortet, sagt es das; warten zwei Sitzungen in diesem Ordner, nennt es das, statt eine auszuwählen.",
    why: "Eine dichte englische Antwort ist nicht immer eine klare, und dasselbe Modell um eine Erklärung zu bitten liefert dieselben Worte. Ein anderer Anbieter liest sie unvoreingenommen. Von Hand sind das fünf Schritte — markieren, kopieren, in den Browser wechseln, neuer Chat, einfügen — mehrmals pro Stunde; hier ist es ein Tastendruck, und die Antwort bleibt im Editor.",
    setup: "Nichts, wenn ein Modell auf **Models** **chat** angehakt ist und einen Chat beantworten kann — ein Chat öffnet sich darauf. **Chat**, in den Settings, enthält den Rest, und alles dort speichert beim Tippen. **Which model a chat opens on** ist ein Optionsfeld für jedes chat-angehakte Modell, das antworten kann, jedes mit einem Feld **Opens with** — womit das Eingabefeld beginnt, wenn dieses Modell gewählt ist; ist keines gewählt, öffnet ein Chat auf dem ersten, das antworten kann, und ein Modell, das keinen Chat beantworten kann, steht mit seinem Grund darunter. **Sending** enthält den Prompt, mit dem die Stelle reist — **What to ask about the selection** —, die Antwortsprache — **Answer in**, standardmäßig Englisch und bewusst nicht die Sprache dieser Seiten — und ob sofort gesendet oder gewartet wird — **Who presses send**. Das Modell ist nicht mehr nur eine Einstellung: der Tab hat eine eigene Auswahl, und was Sie dort wählen, gehört diesem Gespräch und nicht allen künftigen. **CoAI: add the question**, im selben Kontextmenü wie *take the question*, ist derselbe Leser mit dem anderen Verb: Die Frage wird an das angehängt, was im Eingabefeld schon steht, statt es zu ersetzen — der eben verfasste Beitrag behält seine Anweisung und bekommt die Frage darunter als weiteres Material.\n\n**Prompt presets**, der letzte Teil von Chat, sind **Ihre gespeicherten Prompts, jeder mit einem Namen** — einer davon als **main** markiert, und genau der wird genommen, wenn eine Erfassung von selbst sendet. **Add a prompt** fügt einen weiteren hinzu. *What to ask about the selection* ist eine Auswahl darüber: Sie nennt Ihre gespeicherten Prompts, statt eine Kopie davon zu halten, sodass die beiden nicht auseinanderlaufen können. Welchen Ihrer gespeicherten Prompts ein Chat beim Öffnen nimmt, ist das, was sie sich merkt, und leer bedeutet den als main markierten. Was immer im alten einzelnen Prompt stand, wurde beim ersten Lesen dieser Version zu Ihrem ersten benannten Preset — nichts davon ging verloren.\n\n**Ihre gespeicherten Modelle, jedes mit einem Namen**, wurden zu Modellen auf Models — jedes chat angehakt, sein Eröffnungsprompt nun sein Feld **Opens with** hier. Ein gespeichertes Modell, das diese Version nicht lesen kann — eines, das gespeichert wurde, bevor eine Modellvorlage ihren eigenen Anbieter trug —, wird auf Chat mit dem genannt, was zu tun ist: legen Sie es auf Models neu an, chat angehakt. **Edit chat presets**, in der Befehlspalette, bleibt noch ein Release lang erhalten und öffnet die Settings bei Chat.",
    usage: "Die Tastenkombination kopiert die Auswahl selbst und tut dann, was Ihre Einstellung **Who presses send** sagt: sofort fragen oder den Beitrag im Eingabefeld lassen. Die beiden Kontextmenü-Einträge fragen sie nicht — jeder sagt in seinem eigenen Namen, was er tun wird. Kopieren kann das Menü ebenfalls nicht: Das Schließen des Menüs nimmt die Auswahl aus dem Panel, also nimmt es das zuletzt Kopierte. Deshalb steht die Stelle oben im Tab: Sie sehen, was gleich gefragt wird. Ein Tab pro Assistenten-Sitzung, damit sich zwei Gespräche nie mischen.\n\n**Das Eingabefeld bleibt, wo es ist**, und das Gespräch scrollt darüber. Zu einer neuen Antwort wird nur gesprungen, wenn Sie ohnehin unten waren: scrollen Sie zum Lesen nach oben, zieht Sie nichts weg, und **Jump to newest ↓** bringt Sie zurück, wenn Sie wollen. Das Feld wächst beim Tippen bis etwa auf ein Drittel des Fensters und scrollt erst dann. Enter sendet, Shift+Enter ist eine neue Zeile, und es gibt eine **Send**-Schaltfläche für alle, die lieber drücken. Daneben **leert ✕ das Feld** mit einem Druck, und jede ± Steuerung darüber trägt jetzt ein Zeichen — eine Lupe für die Schriftgröße, eine Sonne für den Ton —, damit vier gleich aussehende Schaltflächen nebeneinander keine Reihenfolge mehr sind, die man sich merken muss.\n\n**Antworten werden gesetzt, nicht ausgekippt** — Überschriften, nummerierte und Aufzählungslisten, Tabellen, Code. Links sind blau, und was sie öffnen, ist begrenzt: ein Pfad INNERHALB dieses Arbeitsbereichs öffnet die Datei im Editor, eine `http`- oder `https`-Adresse den Browser; alles andere bleibt Text — ein Pfad, der den Arbeitsbereich verlässt, eine `file://`-URL und eine Adresse, die ein Modell bloß im Satz erwähnt und nicht als Link geschrieben hat. Eine Datei, die nicht gefunden wird, sagt das, statt nichts zu tun. Ihre eigenen Worte stehen rechts, eine Antwort trägt eine Beschriftung mit dem Modell, das sie gab, in dessen Farbe, und eine Linie schließt sie ab — das Ende einer langen Antwort ist damit auffindbar. **Copy answer** gibt Ihnen die ganze Antwort als Markdown, und **Copy block** — unter jedem Codeblock und jedem Zitat — nur diesen einen. Endet ein Modell mit einer Antwort, die es Ihnen zum Weitersenden vorschlägt, und öffnet sie als ```reply-Block, so liest sich dessen Schaltfläche als **Copy the reply prompt**. Allein dieses Kennzeichen erkennt die Erweiterung: dass ein Modell es schreibt, bewirkt Ihr eigener Prompt und nichts, was hinter Ihrem Rücken hinzugefügt wird.\n\n**Die Auswahl fragt erst nach dem Anbieter, dann, welches seiner Modelle antwortet**, denn eine Modellliste gehört einem Anbieter. Mitten im Gespräch zu wechseln ist vorgesehen — der ganze Verlauf geht mit —, und neben der Auswahl steht, was dieses Gespräch bisher gekostet hat. Über dem Feld liegen zwei Reihen Presets: Ihre Modelle in der Farbe ihres Anbieters, derselben, die dieser Anbieter überall sonst hier trägt, und Ihre Prompts in einer Farbe, die kein Anbieter hat — ein Prompt darf nie für einen Anbieter gehalten werden. **Eine Schaltfläche leuchtet nur, solange ihre Worte die geltende Anweisung sind.** Wählen Sie ein Modell von Hand in den beiden Listen, oder löschen Sie die Anweisung aus dem Feld, dann erlischt die Schaltfläche, die sie dort hingeschrieben hat — die Rolle, die eine Modellvorlage hinzufügt, zählt genauso, weshalb das Leeren des Feldes beide erlöschen lässt.\n\n**Ein leeres Feld mit einem anderen gewählten Modell ist ein Nachfragen**: dieselbe Frage geht an das andere Modell und nimmt das Gespräch ohne die Antwort mit, die Sie nicht wollten; die Schaltfläche sagt vorher, wer dran ist. **Fügen Sie einen Screenshot ein**, und er geht mit der nächsten Frage. **Stop** erscheint, während ein Zug läuft, und beendet genau den Zug, für den es gezeichnet wurde, nie den nächsten.\n\n**Sie können weiterfragen, während eine Antwort läuft.** Eine dann gesendete Frage wartet in einer abgedunkelten Liste unter *Thinking…* auf ihren Zug, die älteste zuerst, und ist noch nicht Teil des Verlaufs: jede Zeile hat ein ✕ — **Take this question back** —, das genau diese eine Frage zurückzieht und die anderen stehen lässt. Ein eingefügtes Bild wartet über dem Feld mit einer Schaltfläche **Remove**, bis die nächste Frage es mitnimmt. Eine lange eigene Frage — mehr als fünf Zeilen oder mehr als vierhundert Zeichen — wird auf ihren Anfang eingeklappt, damit die Antworten auf dem Bildschirm bleiben: **Show all … lines** (bzw. characters) klappt sie auf, und **Collapse** klappt sie wieder ein. Eingeklappt werden nur Ihre eigenen Worte, nie eine Antwort.\n\n**Ein gescheiterter Zug sagt, warum, in einem roten Kasten, mit Try again daneben** — angeboten nur, solange das Gespräch noch mit der gescheiterten Frage endet, sodass nie die falsche erneut gestellt werden kann. Und einem Modell, das selbst kein Gespräch behält, muss bei jeder Nachfrage der ganze Verlauf geschickt werden; ein solches Gespräch endet deshalb nach drei Zügen: das Eingabefeld wird durch **Start a new conversation** und **Continue with a local model** ersetzt.\n\n**Asked** steht oben rechts neben den ±-Reglern und zeigt, was SIE in der Claude-Code-Sitzung geschrieben haben, aus der dieser Tab stammt. Nach ein paar Stunden ist die Frage, mit der die Arbeit begann, nach oben aus dem Bild gelaufen, und das Fenster kann nicht mehr sagen, worum es geht — man fragt dann den Assistenten, woran er gerade arbeitet. Die Worte sind nie verschwunden: Dies liest sie aus der Sitzungsdatei, die über den eigenen Titel diesem Tab zugeordnet wird, damit zwei Sitzungen in einem Ordner nie verwechselt werden, und heftet sie über das Gespräch, wo kein Scrollen sie erreicht. `‹` und `›` blättern durch jeden Ihrer Beiträge, den ältesten zuerst. Noch einmal gedrückt klappt es wieder zu — in einer halben Sekunde, nicht ruckartig. Ein aus einer Datei geöffneter Tab hat keine Sitzung hinter sich und deshalb auch keine Schaltfläche.\n\n**Carry nothing above** steht an der letzten Antwort. Ein Druck zeichnet darunter eine strichpunktierte orange Linie: Von da an bekommen ein Modell, zu dem Sie wechseln, und ein Team-Server — dem die ganze Unterhaltung bei JEDEM Beitrag übergeben wird — nur noch, was unterhalb der Linie steht. Gelöscht wird nichts: Das Gespräch bleibt vollständig stehen und lässt sich scrollen und kopieren wie zuvor.\n\nEs heißt nicht „vergiss das“, sondern „trag das nicht weiter“: Das lokale Modell, mit dem Sie sprechen, hält die Unterhaltung im eigenen Prozess und behält jedes Wort. Gespart wird bei den anderen beiden — bei einem Wechsel, der sonst zehn Beiträge zu einem Thema an ein Modell wirft, das Sie zu einem anderen fragen, und bei einem Team-Server, der Ihnen diese zehn Beiträge unter jeder weiteren Frage berechnet.\n\nNoch einmal weiter unten gedrückt, wandert der Punkt dorthin. Rückgängig zu machen gibt es nichts: Die Marke ist eine Position, kein Zustand, und gezeichnet wird immer nur die aktuelle. Sie übersteht ein Neuladen des Fensters zusammen mit dem Gespräch.\n\n**CoAI: switch conversations…** ist die Liste aller Gespräche. `Ctrl+Shift+Alt+G` (`Cmd+Shift+Alt+G` auf dem Mac), das Kontextmenü oder die Befehlspalette. Oben **Open** — was in diesem Fenster gerade in einem Tab steht, mit dem Modell, der Zahl der Beiträge und dem zuletzt Gesagten; darunter **Recent** — alles andere, das Neueste zuerst. Tippen filtert nach dem Titel, nach dem Modell, das geantwortet hat, und nach eben dieser letzten Zeile: ein Gespräch, an das Sie sich über ein einziges Wort seiner Antwort erinnern, ist ein Wort entfernt. Ein offenes wird nach vorn geholt. Ein geschlossenes wird dort wieder geöffnet, wo es aufgehört hat — der ganze Verlauf, nichts läuft, bis Sie fragen, und genau diese erste Frage trägt das Gespräch zu dem Modell hinüber, das sie beantwortet.\n\n**Ein Papierkorb auf jeder geschlossenen Zeile** vergisst dieses Gespräch, und `Alt+Entf` (`Cmd+Entf` auf dem Mac) vergisst das Gespräch unter dem Cursor. Die Liste bleibt in beiden Fällen offen: fünf aufzuräumen sind fünf Tastendrücke und nicht fünf Mal Öffnen. Ein offenes Gespräch hat keinen Papierkorb — schließen Sie erst seinen Tab. **Die Weltkugel im Titel** weitet die Liste von diesem Ordner auf alle Ordner und zurück, und der Titel sagt immer, welches von beiden Sie gerade sehen.\n\n**Vergessen ist nicht Vernichten.** Die Zeile verschwindet sofort und taucht in keiner Liste wieder auf, das Gespräch selbst wird aber auf der Festplatte beiseitegelegt und erst nach denselben neunzig Tagen wie alles andere wirklich gelöscht — ein Tastendruck auf die falsche Zeile kostet Sie also kein Gespräch.\n\n**CoAI: go to conversation** ist der umgekehrte Weg und meist der, den man will. `Ctrl+Alt+G` (`Cmd+Alt+G` auf dem Mac), das Kontextmenü oder die Palette — gedrückt in dem Tab, in dem Sie arbeiten, nicht in einer Liste. Ist das Gespräch in diesem Fenster schon offen, kommt es nach vorn. Ist es nur gespeichert, öffnet es sich wieder und wird an diesen Tab gebunden, sodass jeder weitere Druck an derselben Stelle landet. Ist für den Tab nichts gespeichert, öffnet sich die Liste mit **New conversation for it** unter dem Cursor — und es entsteht nichts, bis Sie es drücken, denn ein Tastenkürzel trifft man leicht versehentlich. Drücken Sie es, öffnet sich das gewohnte **Chat with other AI** für diesen Tab, aus dem, was dort markiert ist. Und aus einem Terminal, dem Output-Bereich oder überall dort, wo ein Gespräch nicht hingehören kann, öffnet sich die vollständige Liste statt gar nichts.\n\n**CoAI: back to where this chat came from** ist der Weg zurück. Rechtsklick in einer Unterhaltung, oder dasselbe `Ctrl+Alt+G` (`Cmd+Alt+G`), während die Unterhaltung der aktive Tab ist, und der Claude-Code-Tab oder der Editor, aus dem sie geöffnet wurde, kommt nach vorn. Nach einem Neuladen des Fensters ist dieser Tab ein neuer, daher öffnet der Befehl stattdessen die Claude-Code-Sitzung, die die Unterhaltung festgehalten hat, oder ihre Datei. Eine Unterhaltung, die beides nicht kennt, sagt das, statt nach einem Namen zu raten.\n\n**New chat** in der Kopfzeile des Tabs fängt im selben Tab neu an. Das Gespräch, in dem Sie waren, wird archiviert — es liegt vollständig in **CoAI: switch conversations…** unter demselben Namen — und der Tab gehört wieder Ihnen, leer, und das Zitat, mit dem das alte begann, ist weggeräumt. Modell, Prompt und der Name des Tabs bleiben, wie sie waren, und die nächste Frage erreicht ein Modell, das nichts davon gehört hat. Genau darum geht es: ein langes Gespräch über eine Sache ist ein Modell, das sie immer noch mit sich trägt, wenn Sie nach einer anderen fragen — und auf einem Team-Server ist es zusätzlich das ganze Gespräch, das mit jeder Frage erneut gesendet und berechnet wird. Läuft noch eine Runde, wird sie zuerst beendet und abgewartet, damit die Antwort, auf die Sie gewartet haben, in dem archivierten Gespräch bleibt. Die Schaltfläche im Hinweis „dieses Gespräch ist voll“ ist dieselbe.\n\n**Wo es sich nicht sicher sein kann, fragt es.** Zwei Claude-Sitzungen gleichen Namens oder ein Gespräch über diese Datei, das unter einem anderen Ordner desselben Fensters liegt, öffnen die Liste auf genau diese eingeschränkt — mit einem Titel, der sagt warum, und mit dem Namen des Tabs bereits im Suchfeld, sodass das Gesuchte fast immer oben steht. Ein Backspace zeigt wieder alles. **Und wurde genau ein gespeichertes Gespräch aus einem Tab dieses Namens geöffnet — und ist gerade genau ein Tab dieses Namens offen —, öffnet es dieses, statt zu fragen** — wo es eine Antwort hat, nutzt es sie, und wo es nur eine Vermutung hat, zeigt es Ihnen die Vermutung.",
    whatCanGoWrong: "Das Kopieren der Auswahl braucht eine Windows-Sitzung: die dieses Rechners oder — aus einem WSL-Fenster — die, an der dieses Fenster hängt. Anderswo sagt die Tastenkombination das und verweist auf das Menü, das überall funktioniert. Lässt sich der Helfer nicht erreichen, oder startet er und wird nicht fertig, benennt die Meldung genau das, statt Ihre Auswahl zu beschuldigen. Stirbt der Prozess des Modells, sagt die Antwort danach, dass das Gespräch neu begonnen hat, denn an die früheren Züge erinnert es sich dann wirklich nicht. Ein Modell auf einer anderen Laufzeit wird namentlich abgelehnt, statt still zu fehlen — der Chat spricht bisher ein einziges Protokoll. Ein Neuladen des Fensters bewahrt das GESAGTE: jeder offene Chat-Tab kommt mit seinen Fragen und Antworten zurück, samt einer Zeile, dass das Gespräch durch das Neuladen geschlossen wurde. Das Modell dahinter ist fort — nichts läuft, bis Sie erneut fragen, und diese erste Frage trägt das Protokoll in eine neue Sitzung: das ist der Preis — oder, wenn Sie das Gespräch markiert haben, nur das unterhalb der Marke.\n\n**Ein Bild wird NAMENTLICH abgelehnt, statt ins Leere geschickt zu werden.** `codex` wird als UNGETESTET abgelehnt, nicht als unfähig — sein Konto lief mitten in der Messung in ein Limit, und das ist ein anderer Satz als ein gemessenes Nein —, und ein Reviewer auf einem Team-Server hat auf der Leitung noch gar keinen Platz dafür. Ein SVG wird abgelehnt, obwohl es ein Bild ist: es ist Markup mit Skript darin, und was hier geschieht, ist eine Datei an einen Prozess zu geben, der sie öffnen wird.\n\n**Die laufende Summe trägt bei zwei von drei Anbietern eine Tilde.** Nur `claude` meldet, was es berechnet hat; bei den anderen wird die Zahl aus Tokens hergeleitet, und ein geschätzter Zug macht die ganze Summe zur Schätzung. Die genaue Aufzeichnung, Zug für Zug, steht im Tab **Conversations** von **Show review rounds**. Und sie steigt: eine Frage an einen Team-Server trägt das ganze Gespräch mit, also ist ein langer Verlauf dort langsamer und teurer als ein kurzer. Das Mittel ist **Carry nothing above**, ohne den Verlauf zu verlieren — oder eine frische Stelle zu erfassen.\n\n**Ein Gespräch, das die Liste anbietet, kann schon fort sein.** Die Liste wird im Hintergrund aufgebaut und im Speicher gehalten — damit sie sofort aufgeht, statt Tausende Dateien zu lesen, während Sie warten —, und deshalb kann ein anderes Fenster ein Gespräch vergessen, zwischen dem Zeichnen der Liste und Ihrem Druck darauf. Dann wird es gesagt und die Zeile verschwindet, statt dass sich ein Tab auf nichts öffnet. Ein Gespräch, das DA ist und nicht gelesen werden kann, ist ein anderer Satz und behält seine Zeile: ein Ordner, der nicht geantwortet hat, oder ein Eintrag, den eine neuere Version dieser Erweiterung geschrieben hat, hat nichts verloren und geht wieder auf, sobald es geht.\n\n**Ein Gespräch, das in einem anderen VS Code-Fenster offen ist, steht in der Liste, lässt sich hier aber nicht öffnen.** Die Zeile sagt das, und ein Druck darauf sagt Ihnen, wo es ist. Ein Fenster kann kein anderes Fenster in den Vordergrund holen, und ein zweiter Tab auf dasselbe Gespräch gäbe ihm zwei Schreiber, die sich gegenseitig überschreiben — am Ende wäre das Gespräch in zwei Teile zerfallen. Wechseln Sie stattdessen in jenes Fenster. Aus demselben Grund lässt es sich von hier aus auch nicht vergessen: der Tab, der es hält, würde es einfach zurückschreiben.",
  },
  "the-question-consultant": {
    title: "Der Question consultant: andere Modelle antworten, bevor Sie gefragt werden",
    whatItIs: "Bevor eine KI IHNEN eine Frage stellt, kann sie sie dem Question consultant stellen — dem Werkzeug `ask_consultants`. Jede Zeile, die Sie in **Consultants › Question consultant** eingeschaltet haben, antwortet sofort: eine Zeile ist ein Modell mit genau einem Basis-Prompt — die anderen Projekte auf dieser Platte studieren, im Internet suchen oder die Meinung des besten Entwicklers geben —, und jede Antwort geht einzeln an die KI zurück, als Rat gekennzeichnet. Während die Modelle arbeiten, steht die Frage in der Seitenleiste unter **Active questions**; jede gestellte Frage ist eine Zeile im Tab **Questions** von **Show review rounds**.",
    why: "Eine KI, die allein arbeitet, hält Sie mit Fragen auf, die ein anderes Modell hätte beantworten können. Drei Modelle mit drei verschiedenen Blickwinkeln beantworten die meisten davon in wenigen Minuten, und Sie werden nur gefragt, was sie nicht klären konnten. Solange die KI einen Plan umsetzt, macht das Gate daraus eine Regel statt einer Gewohnheit; bei einer Frage, die die Produktion lahmlegen könnte, während ein Plan entsteht, werden zuerst die Berater gefragt, und ihre Antworten kommen mit der Frage — bei einem haltenden Gate kommt die Karte sofort, und die Berater laufen nebenher.",
    setup: "**Let an AI ask the question consultant first** ist der Schalter. **Before it asks you** legt fest, was das Gate vor `ask_human` mit einer Frage macht, die sie übersprungen hat: *Require* weist sie ab, solange ein Plan umgesetzt wird — nach den ersten Fragerunden des Plans und bis zu seinem Stage-Release —, *Remind* erinnert nur, *Off* sagt nichts. Ein Produktionsrisiko mit Begründung wird nie zurückgehalten.\n\n**Who answers** listet die Zeilen. **Add a row** fügt eine ausgeschaltete hinzu; wählen Sie ihr **Model** aus den Modellen, die auf **Models** **question consultant** angehakt sind — auch ein API-Modell, etwa Grok über OpenRouter mit dem Namen seines Tresorschlüssels —, und ihren **Prompt**. Die Zeile oben an diesem Ort nennt die angehakten Modelle, und **Change on Models** bringt Sie zu ihnen; die eigenen Einstellungen eines Modells werden dort auf seiner Karte bearbeitet. Höchstens sechs Zeilen dürfen gleichzeitig an sein, und derselbe Prompt darf auf mehreren Zeilen stehen. Ein Prompt, den die Laufzeit der Zeile nicht bedienen kann, steht in der Liste, ist aber deaktiviert, mit dem gemessenen Grund: Antigravity kann nicht im Web lesen, eine API-Zeile liest keine Platte. Eine Codex-Zeile und Antigravity auf der Platte **can read this machine** — kein Flag schränkt sie ein —, also sagt die Zeile das mit einem Häkchen **Can read this machine**, das immer gesetzt ist und sich nicht entfernen lässt.\n\n**Base prompts** zeigt die drei mitgelieferten Prompts und Ihre eigenen, jeweils mit der Fähigkeit, die er braucht. Einen mitgelieferten bearbeiten Sie in seinem Feld — **Restore default** stellt den Originaltext wieder her — oder Sie legen mit **Add a prompt…** einen eigenen an. **Folders a disk row may read** sind die einzigen Orte, die eine Plattenzeile liest, nur lesend: ein Laufwerksstamm, Ihr Profilordner selbst, ein Systemordner oder der Datenordner werden abgewiesen. Ein Ordner in der Schreibweise des anderen Betriebssystems — ein WSL-Pfad in einem Windows-Fenster oder ein Windows-Pfad in WSL, denn beide Fenster teilen diese Einstellungen —, der auf diesem Rechner kein Ordner ist, gehört der anderen Seite (einer, der es ist, etwa /work auf einem Windows-Laufwerk, gehört dieser Seite): Er wird so markiert, der Server dieser Seite überspringt ihn, und der Server auf der anderen Seite liest ihn. Gehören alle Ordner der anderen Seite, wird eine Plattenzeile auf dieser Seite nicht gefragt. **Minutes one row may run**, **Questions per session** und **Question batches that reach you first** sind die Grenzen.",
    usage: "Sie drücken nichts. Die KI ruft `ask_consultants` mit ihrer Frage und dem, was sie versucht hat, auf; **Active questions** in der Seitenleiste zeigt die Frage mit einer Zeile pro Modell — *consulting*, dann *answered*, *timed out* oder *failed*, mit der Dauer —, und die Zeile rückt vor, sobald ein Modell fertig ist.\n\nFragt die KI Sie danach, fragt sie in ihrem eigenen Chat: `ask_human` schickt die eigenen Fragen der KI dorthin zurück — mit den Antworten der Berater, wenn sie wegen eines Produktionsrisikos zuerst gefragt wurden — und schreibt keine Karte. Nur eine Frage, die gestellt wird, während das Review-Gate hält, wird zu einer Karte in **Active questions**, darunter etwaige Antworten eingeklappt und ein Produktionsrisiko mit seinem Grund markiert. **Answer…** darauf öffnet zuerst ein Feld für Ihre eigenen Worte und danach die Auswahlmöglichkeiten des Gates. Eine Karte, die fünfzehn Minuten lang niemand beantwortet, läuft ab: Die KI soll im Chat fragen, und die Karte verlässt die Seitenleiste.\n\nDer Tab **Questions** von **Show review rounds** behält eine Zeile pro Frage — wann, wo, wie viele Modelle geantwortet haben, was es gekostet hat, wie lange es dauerte und was danach geschah — und klappt zu einer Zeile pro Modell mit Prompt, Status und Rat auf.",
    whatCanGoWrong: "**Eine Antwort einer Zeile, die diese Maschine lesen kann, trägt diese Kennzeichnung** in der Seitenleiste und im Log, neben der Antwort selbst. Die Zeilen sind Modelle anderer Anbieter, und ihre Antworten sind Material, keine Anweisungen: Die KI wird angewiesen, sie zu prüfen.\n\nEin Modell, das in seinen Minuten nicht antwortet, gilt als timed out, und die anderen antworten trotzdem. Niemand zu fragen — keine Zeile an, die Fragen der Sitzung aufgebraucht, der Schalter aus — blockiert die KI nie: Das Gate lässt die Frage durch und sagt warum. Ein älterer coai-mcp hat gar keinen Question consultant; der Tab sagt das in einem Banner und schreibt keine seiner Einstellungen, bis der Server aktualisiert ist.",
  },
  "the-consultant": {
    title: "Der Berater: ein zweiter Anbieter für eine festgefahrene KI",
    whatItIs: "Ein Werkzeug namens `consult`, das Ihr Assistent SELBST aufruft, wenn er zum zweiten Mal um denselben Fehler kreist. Es übergibt das Problem dem Modell eines anderen Anbieters, zusammen mit diesem Arbeitsverzeichnis und den noch nicht committeten Änderungen — jenes Modell liest den Baum NUR LESEND und antwortet mit einem Rat.\n\nNichts davon wird angewendet. Die Antwort kommt eingezäunt und als beratend markiert zurück, dem Assistenten wird ausdrücklich gesagt, dass es eine Meinung über Code ist, den der Berater nicht ändern kann, und die Korrektur wird weiterhin hier geschrieben und geprüft. Es ist ein Gespräch und keine Frage: ein paar Züge, damit das zweite Modell sagen kann „probieren Sie das, und sagen Sie mir, was ausgegeben wurde“ — und die Antwort auch hört.",
    why: "Zwei Runden derselben falschen Korrektur sind das Teuerste, was ein Assistent tut, und ausgerechnet das Modell, das den blinden Fleck erzeugt hat, kann ihn nicht sehen. Ein anderer Anbieter liest denselben Baum unvoreingenommen.\n\nVon Hand hieße das: einer zweiten KI das Problem noch einmal beschreiben — ohne Repository, ohne Diff und meist ohne das, was schon versucht wurde. Genau deshalb ist die zweite Antwort so oft die erste. Hier stellt der Server alle drei Teile selbst zusammen; der Assistent schickt nur das Problem in eigenen Worten.",
    setup: "**Let an AI consult another vendor** ist der Schalter, in **Consultants › Consultant**. Er ist an und tut nichts, solange kein Assistent fragt.\n\nDarunter eine Auswahl je Art von Aufrufer — **Claude Code asks**, **Codex asks**, **Gemini asks**, **Another client asks** —, denn wen eine festgefahrene KI fragt, hängt davon ab, welche KI feststeckt. Jede bietet **The shipped pair** an — Claude Code fragt `codex`, Codex fragt `claude`, Gemini und alles andere fragen `codex`, niemals sich selbst — und jedes Modell, das auf **Models** **consultant** angehakt ist. Die Zeile oben an diesem Ort nennt die angehakten Modelle, und **Change on Models** bringt Sie zu ihnen. Ein Modell, dessen Laufzeit kein Gespräch führen kann, lässt sich nicht als consultant anhaken — sein Häkchen ist ausgegraut, mit dem Grund —, und ein Team-Server-Modell wird nie angeboten: eine Konsultation geht nie über einen. Unter jeder Auswahl sagt eine Zeile, worauf der Konsultant dieses Aufrufers läuft, und darunter steht sein Zustand: was der Server von ihm weiß, und ein bezahltes **Check** für diese Seite.\n\n**Modell, Effort und Prompt des Konsultanten gehören seiner Karte**, auf Models: eine Wahl ist ein Verweis auf diese Karte, wer die Karte bearbeitet, bearbeitet also den Konsultanten, und ein Modell kann zugleich prüfen und beraten. Die Wahl eines Modells, das nicht mehr consultant angehakt oder gar nicht mehr da ist, bleibt sichtbar und benannt, bis Sie sie ändern — sie wird Ihnen nie unter der Hand gelöscht. Ein Modell vom eigenen Anbieter des Aufrufers zu wählen ist erlaubt, und die Auswahl sagt, was davon zu halten ist: es lohnt sich nur mit einem stärkeren Modell, denn der Server sieht, welcher Anbieter fragt, und nie dessen Modell.\n\n**What the consultant is asked to do** ist das Feld für die Anweisungen, die er vor dem Problem erhält. Leer ist der Prompt, mit dem dieser Build ausgeliefert wird — der Tab kann Ihnen diese Worte nicht zeigen, weil sie in den Server einkompiliert sind. Was Sie tippen, wird in die Prompt-Überschreibung des Servers geschrieben und bei der nächsten Konsultation gelesen. **Restore default** nimmt die Überschreibung weg, und das Feld zu leeren tut dasselbe: einen Prompt, der nichts sagt, gibt es nicht.",
    usage: "Sie drücken nichts. Das Snippet in Ihrer `CLAUDE.md` sagt dem Assistenten, wann es so weit ist — derselbe Fehler zweimal, oder Ihr Satz, dass es immer noch nicht behoben ist — und er ruft das Werkzeug selbst auf.\n\nDrei Zahlen begrenzen das. **Turns per consultation** ist, wie oft eine Beratung gefragt werden darf, standardmäßig fünf; dem Berater wird in JEDEM Zug gesagt, wie viele bleiben, damit der letzte antwortet statt eine weitere Rückfrage zu stellen. **Calls per session** ist, wie viele Aufrufe der Art stuck eine Assistentensitzung in 24 Stunden machen darf — die erste Frage und jede Nachfrage gleichermaßen —, standardmäßig zehn. **Close an idle consultation after, minutes** schließt einen liegengebliebenen Faden — geprüft jede Minute, solange der Server läuft; eine spätere Frage ist dann eine neue Beratung mit vollem Budget.\n\n**Solange eine Beratung läuft, steht sie in der Seitenleiste**, in **Active consultations**, dem Abschnitt unterhalb von **Active gates**: wer wen fragt, der wievielte Zug es ist, und der Hinweis zum Arbeitsverzeichnis, falls er ausgelöst wurde. Endet sie, verschwindet sie — die Seitenleiste zeigt nur Laufendes — und jede Beratung, die es gegeben hat, ist eine Zeile in **Show review rounds** unter *Consultations*: woran es klemmte, was geraten wurde und was es gekostet hat.\n\nPing-Pong ist ausgeschlossen: eine in dieser Beratung bereits gestellte Frage wird abgelehnt, gleich in welchem Zug, der nächste Zug geschieht also erst, wenn Ihr Assistent wirklich etwas probiert hat und berichten kann. Was jede Beratung gekostet hat, steht in **Show review rounds**, neben den Review-Runden und den Chats.\n\n**Consultation cadence** holt einen Berater, auch wenn niemand festsitzt. Sobald ein Plan in Epics zerlegt ist, schuldet jede Gruppe von Epics vor ihrer ersten Code-Runde eine Beratung — stimmt diese Gruppe, wo ist sie schwach, was hat sie vergessen —, und die Anweisung dazu, mit dem fertig ausgeschriebenen `consult`-Aufruf, steht in jeder Review-Antwort, bis sie eingelöst ist. **One consultation per this many epics** ist standardmäßig drei. Ab **Ask for the riskiest pieces from this many epics** — fünf — wird der Assistent außerdem gefragt, welche Epics und Stories das größte Risiko tragen, und jedes, das er nennt, bis zu **Riskiest pieces per plan, at most**, bekommt eine eigene Beratung. *Remind* gibt die Anweisungen und lehnt nichts ab; *Require* lehnt die erste Code-Runde einer Gruppe ab, bis ihre Beratung mit einem Ergebnis geschlossen ist; *Off* gibt keine Anweisungen. Ein Berater, der nicht erreichbar ist, blockiert die Arbeit nie: Die Runde läuft durch, und der Grund steht darauf. **Jede Beratung hat eine Art (kind)** — auf ihrer Karte in der Seitenleiste, im Server-Log und in der Spalte **Kind** unter *Consultations* in **Show review rounds**: **stuck** — der Assistent hat von sich aus gefragt, weil er festsaß; **cadence** — das Gate hat sie für eine Gruppe von Epics angeordnet; **risk** — für ein Stück, das der Assistent als riskant benannt hat. Bei einer angeordneten sagt **For**, welche Epics oder Story und welcher Plan. **Turns per consultation** und das Schließen nach Leerlauf gelten für jede Art; **Calls per session** zählt nur stuck, weil das Gate die anderen anordnet und selbst begrenzt: eine offene oder mit Ergebnis geschlossene Beratung je Gruppe oder riskantem Stück, eine neue erst nach einer gescheiterten oder ohne Ergebnis abgelaufenen. Eine angeordnete Beratung, die wegen Leerlauf geschlossen wurde, zählt für ihre Gruppe nicht mehr, bis jemand festhält, wie sie ausging. Der Schalter **Let an AI consult another vendor** schaltet alle drei Arten ab — eine cadence auf *Require* nimmt ihre Ablehnung dann zurück, und der Grund steht auf der Runde.",
    whatCanGoWrong: "**Der Berater kann nicht in Ihr Repository schreiben, und der Server prüft, statt zu vertrauen.** Er nimmt vorher und nachher einen Fingerabdruck des Baums; eine Beratung, WÄHREND DER sich der Baum GEÄNDERT hat, schlägt fehl und wird gemeldet, statt beantwortet zu werden — die Prüfung sieht, DASS sich etwas bewegt hat, nie WER, sodass auch Ihre eigene Änderung während des Wartens sie auslöst. Gelöscht oder zurückgesetzt wird dabei nichts — eine Datei, die Sie beim Warten geschrieben haben, gehört Ihnen, und sie an eine Sicherheitsprüfung zu verlieren wäre schlimmer als das, wofür die Prüfung da ist.\n\n**Ein Rat ist Material, keine Anweisung.** Er kommt in einem Zaun, der nennt, welcher Anbieter ihn geschrieben hat und dass er nur beratend ist — damit Text in einem Repository, der an eine KI gerichtet ist, nicht dadurch befolgt wird, dass er Ihrer vorgelesen wird.\n\n**Das Gespräch liegt im Speicher des anderen Anbieters**, denn genau das macht eine Nachfrage möglich, und es enthält die uncommitteten Änderungen dieses Repositories. Das ist der Preis der Funktion, und es steht uns nicht zu, dort etwas zu löschen. Schalten Sie die Funktion ab, lehnt das Werkzeug namentlich ab: einem Assistenten wird gesagt, dass sie aus ist, statt ihn rätseln zu lassen, warum nichts zurückkam.",
  },
  "install-the-server": {
    title: "Hier anfangen: den MCP-Server installieren",
    whatItIs: "Die Erweiterung ist das Gesicht. Das Review macht `coai-mcp`, ein kleines Programm, das Ihr KI-Assistent startet und mit dem er spricht. Solange es nicht installiert ist, reviewt niemand.",
    why: "Ein Review muss dort laufen, wo Ihr Code liegt, Hersteller-CLIs starten und minutenlang arbeiten. Das kann eine VS-Code-Erweiterung nicht, und ein Server, der einem VS-Code-Fenster gehörte, würde mit ihm sterben.",
    setup: "Öffnen Sie **Setup › MCP server** in den Settings. Dort steht, was installiert und was veröffentlicht ist, und eine Schaltfläche, wenn beides auseinandergeht — drücken Sie sie. **Install the MCP server…** im ⋯-Menü der ConnectOtherAIs-Seitenleiste ist dieselbe Installation durch die andere Tür. Der Download wird gegen die `.sha256` des Releases geprüft, die Binärdatei landet im privaten Speicher der Erweiterung und kommt nicht in den `PATH`.\n\nDie Installation legt den MCP-Konfigurationsblock in Ihre Zwischenablage; **Copy the MCP config block**, im ⋯-Menü der ConnectOtherAIs-Seitenleiste, kopiert ihn erneut, wann immer Sie ihn brauchen. Fügen Sie ihn in die Konfiguration Ihres Assistenten ein. Das passiert EINMAL. Starten Sie den Assistenten neu, damit er den Server hochfährt.",
    usage: "Danach kommen Sie selten zu **Setup › MCP server** zurück: die veröffentlichte Version wird höchstens halbstündlich neu abgefragt, **Check again** fragt sofort.\n\nJede Plattform hat ihre eigene Binärdatei. Zu jedem Release erscheinen Builds für Windows, macOS und Linux; eine Maschine ohne eigenen Build sagt das ehrlich, statt einen fremden zu laden.",
    whatCanGoWrong: "Steht in **Setup › MCP server**, die veröffentlichte Version sei nicht lesbar, wurde GitHub nicht erreicht. Nichts ist kaputt, der installierte Server läuft.\n\nSteht dort *The installed coai-mcp could not report its reviewers*, wurde der Server gefragt, welche Reviewer er ausführen würde, und gab keine Antwort — also kann keine Karte auf **Models** sagen, ob coai-mcp dieses Modell ausführen würde. Das ist eine Tatsache über die Binärdatei, nicht über ein einzelnes Modell, und deshalb wird es hier gesagt und nicht als Abzeichen auf jeder Karte; ein Update behebt es meist.\n\nZeigt Ihr Assistent nach dem Einfügen keine Werkzeuge, wurde er nicht neu gestartet. Im Block steht der exakte Pfad zur Binärdatei; ein von einer anderen Maschine kopierter Block zeigt auf einen Pfad, den es hier nicht gibt.",
  },
  "choose-reviewers": {
    title: "Dann: wählen Sie, wer prüft",
    whatItIs: "**Models**, der erste Tab der Settings, ist jedes Modell, das diese Seite nutzen kann, einmal angelegt — und die Runde fremder Modelle, die Ihren Plan und Ihren Code lesen wird, sind die Modelle, die zum Prüfen angehakt sind. Jedes Modell ist eine Karte. Ihr Kopf trägt einen Schalter, der es einschaltet, seinen Namen, **✓ Check**, **⧉ Duplicate** und **✕**; darunter sagen Abzeichen, wie es läuft — eine CLI auf diesem Rechner, ein API-Schlüssel, die GPU dieses Rechners oder ein Team server — und was coai-mcp von ihm sagt, und eine Karte, die hier eine CLI startet, hat ein ▶, um diese CLI im Terminal zu öffnen, ein ⤓, um sie zu installieren, und ein ⟳, das grün wird, sobald eine neuere Version veröffentlicht ist.\n\n**Use for** ist, wofür das Modell da ist. Zuerst kommen die Review-Stufen — **reviews plans**, **reviews code**, **reviews documents** und **reviews features** —, dann die anderen Verwendungen: **security lane**, **consultant**, **question consultant**, **chat** und **Bugz ranking**, jede mit ihrem Grund ausgegraut, wo ein Modell dieser Laufzeit sie nicht übernehmen kann. **How it answers** enthält sein **Model**, seinen Effort und seinen eigenen System-Prompt; **Connection** und **Price**, eingeklappt am Fuß der Karte, enthalten seinen Endpunkt, seinen CLI-Pfad und seine Preise pro Million Token. Ein Modell kann mehrmals mit unterschiedlichen Einstellungen angelegt werden.\n\n**reviews features** ist, ob dieses Modell ein ganzes FEATURE reviewen soll — einmal, am Ende eines Plans mit drei oder mehr Epics, vor dem Release. Es ist aus, bis Sie es setzen, es braucht coai-mcp 0.39.0 oder neuer, und ein Team-Server-Modell kann es noch nicht haben — sein Häkchen ist aus und sagt, warum.\n\nÜber den Karten grenzen **Find a model**, **Runs on** und **Show switched-off models** die Liste ein, und drei Filterzeilen — **Used for**, **Effort** und **Runs on** — grenzen sie danach ein, wofür jedes Modell angehakt ist, nach seinem Effort und nach seiner Laufzeit. Das Eingrenzen ändert nichts Gespeichertes.",
    why: "Der ganze Punkt ist, dass der Prüfer nicht der Autor ist. Eine zweite Meinung desselben Modells, das den Code geschrieben hat, ist weniger wert als eine erste Meinung eines anderen — und zwei Anbieter, die sich auf einen Befund einigen, sind das stärkste Signal, das dieses Produkt hervorbringt.",
    setup: "**＋ Add a model**, über den Karten, fragt, wo das Modell läuft — eine CLI hier, ein API-Schlüssel, die GPU dieses Rechners oder ein Team server — und bietet die Anbieter an, die dieser Build kennt: Codex, Antigravity (Gemini, Claude und GPT-OSS über ein Abonnement), ein zweites Claude, DeepSeek, OpenRouter, **API (OpenAI-compatible)** — ein gehosteter Endpunkt wie xAI oder DashScope, direkt mit einem Schlüssel aus dem Tresor erreicht, ohne CLI dazwischen: Basis-URL eintragen und die Modell-Id tippen — und eine leere Vorlage für jeden OpenAI-kompatiblen Endpunkt über die Codex-CLI. Dann haken Sie auf seiner Karte an, wofür das neue Modell verwendet wird.\n\nDie meisten authentifizieren sich selbst: ist die CLI auf dieser Maschine angemeldet, braucht es keinen Schlüssel. ▶ auf einer Karte öffnet ein Terminal mit dieser CLI — dort melden Sie sie an, und dort steht ihr eigener Verbrauchsbefehl schon getippt und wartet auf Enter. ⤓ öffnet dasselbe Terminal mit dem INSTALLATIONS-Befehl — dem offiziellen des Anbieters, für das Betriebssystem, in dem dieses Terminal wirklich läuft. VS Code an WSL angebunden bekommt den Linux-Befehl, nicht den PowerShell-Befehl.\n\n**Ein Team server ist der andere Weg zu einem Reviewer, und er braucht hier nichts Installiertes.** Ein Rechner irgendwo führt die Hersteller-CLIs auf EINEM Firmenabonnement aus, und alle melden sich dort mit ihrem Arbeitskonto an, statt ein eigenes zu kaufen. Fügen Sie einen unter **Setup › Team servers** hinzu, drücken Sie **Sign in**, und seine Anbieter erscheinen in **＋ Add a model** mit den Konten, die sie frei haben. Ihr Plan und Ihre Diffs werden an diesen Rechner geschickt, was **Setup › Team servers** in einer eigenen Zeile sagt — dass es der eigene Server der Firma ist, macht es nicht weniger wahr, dass der Code diesen hier verlässt.",
    usage: "**⟳ sagt Ihnen VOR dem Drücken, ob es etwas zu aktualisieren gibt.** Grün heißt, der Anbieter veröffentlicht eine neuere Version als die auf dieser Maschine; grau heißt, Sie sind auf der neuesten — oder eine der beiden Zahlen war nicht lesbar. Beide stehen im Tooltip, die Farbe ist also nie das einzige Signal. Ein Druck öffnet ein Terminal mit dem eigenen Update-Befehl dieser CLI, getippt und wartend: `claude update`, `agy update` und `codex update` ab codex 0.126.0. Die Gemini CLI sowie ein Codex älter als 0.126.0 oder mit einer Version, die sich nicht lesen ließ, werden über npm mit `@latest` neu installiert — die Zeile, die OpenAI und Google zum Aktualisieren drucken.\n\nZwei Prüfer sind das nützliche Minimum, weil Übereinstimmung das Signal ist. Drei kosten dreimal so viel und sagen selten dreimal so viel.\n\n**✓ Check** schickt nach einer Rückfrage einen echten, bezahlten Zug an dieses Modell, in einem Wegwerf-Ordner; was dabei herauskam, bleibt als eigenes Abzeichen auf der Karte, getrennt vom Urteil von coai-mcp. **⧉ Duplicate** legt eine Kopie mit eigener id an — etwa dasselbe Modell mit einem anderen Effort.\n\nDie Auswahl **Model**, unter **How it answers**, zeigt, was diese CLI auf dieser Maschine wirklich erreicht: bei Codex der eigene Modell-Cache, bei den anderen eine geprüfte Liste. **another model…** nimmt jede exakte id.\n\n**Die eigenen Einstellungen eines API-Reviewers.** Auf einer *API (OpenAI-compatible)*-Karte gibt es, sobald coai-mcp meldet, was ihr Modell annimmt, drei weitere Bedienelemente: **thinking** (nur wenn der Anbieter dokumentiert, wie sich das Nachdenken abschalten lässt — sonst sagt die Karte, dass es sich nicht abschalten lässt), **effort** (eine Auswahlliste mit genau den Stufen, die dieser Anbieter annimmt; die kalibrierte ist markiert) und **max review time (minutes)**. Jedes beginnt bei dem, was die Kalibrierung für dieses Modell festgelegt hat. Die Voreinstellung zu wählen speichert nichts, sodass die Zeile der nächsten Kalibrierung folgt; ein von Ihnen gesetzter Wert hat sein eigenes **reset to calibrated default**. Eine Einstellung, die der Server ablehnt, zeigt die Karte mit seiner Begründung. Das braucht coai-mcp 0.40.0 — bei einem älteren blendet die Karte sie aus und sagt es.\n\n**Der Rest einer Karte.** Eine Karte, die eine CLI auf diesem Rechner startet, hat ein Feld **CLI path** — leer heißt, sie wird im `PATH` gesucht, was fast überall richtig ist und in WSL falsch: dort können `codex` und `gemini` auf die Windows-npm-Shims auflösen und an einer fehlenden Linux-Binärdatei sterben; tragen Sie dort den nativen Pfad ein. Ein CLI-Pfad, der für das andere Betriebssystem geschrieben ist — ein WSL-Pfad in einem Windows-Fenster, ein Windows-Pfad in WSL, denn beide Fenster teilen diese Einstellungen —, gehört der anderen Seite: Die Karte sagt es unter dem Feld, und diese Seite sucht die CLI stattdessen im `PATH`; hier wird er nie gestartet, und coai-mcp überspringt ihn ebenfalls. Eine API-Karte hat keinen CLI-Pfad, denn ihre CLI ist coai-mcp selbst. Sie hat stattdessen eine Auswahl **dialect** — wie die Anfrage für die Familie dieses Endpunkts formuliert wird; `openai` ist der allgemeine, und der eigene eines Anbieters kommt erst hinzu, wenn er gegen den echten Endpunkt gemessen wurde — und ein drittes Preisfeld, **$ / 1M cached**: ein Anbieter, der ein Prompt-Präfix zwischenspeichert, berechnet gecachte Eingabe zu einem Bruchteil des Eingangspreises, und der Server bepreist die Züge dieser Karte selbst.",
    whatCanGoWrong: "Das einzige Modell, das für Plan- oder für Code-Review eingeschaltet ist, kann weder ausgeschaltet noch entfernt werden — sein Schalter und sein ✕ sagen, warum: eine Runde ohne Teilnehmer prüft nichts.\n\n**Eine Karte, von der der Server sagt, dass er sie nicht ausführen kann, trägt neben ihrem Namen ein Abzeichen cannot review.** Fahren Sie mit der Maus darüber, um den Grund zu sehen — das Einzige, woran ein Mensch etwas tun kann. Das Urteil ist, wie coai-mcp Ihre Einstellungsdatei auf diesem Rechner liest, und das Abzeichen sagt das auch: eine Variable in der eigenen Konfiguration Ihres MCP-Clients schlägt diese Datei, also kann der laufende Server anderer Meinung sein. Eine Karte, nach der der Server nicht gefragt wurde oder die er nicht erwähnt hat, zeigt überhaupt kein Abzeichen — ein Abzeichen, das bei einer fehlgeschlagenen Prüfung aufleuchtet, wäre ein Abzeichen, das lügt.\n\nEin Anbieter, dessen CLI nicht installiert ist, sagt das in **providers** vor einer Runde, nicht mitten darin. Gemini ist eigens als RETIRED markiert — Google hat Code Assist für Einzelkonten geschlossen, und diese CLI verweigert nun, bevor sie ein Modell erreicht. Nehmen Sie Antigravity.\n\nEin Team-Server-Modell, das nicht ausgeführt werden kann, trägt dasselbe Abzeichen, und sein Tooltip sagt, warum: *not signed in* (drücken Sie Sign in unter **Setup › Team servers**), *sign in again* (die Sitzung ist abgelaufen) oder *outside the company domain* (das behebt eine neue Anmeldung nicht). **Setup › Team servers** zählt außerdem, wie viele Konten jedem seiner Anbieter bleiben — alle abgemeldet ist Sache des Betreibers, alle im Ratenlimit kommen von selbst zurück.",
  },
  "a-local-model": {
    title: "Ein Modell auf dem eigenen Rechner als Prüfer",
    whatItIs: "Ein Prüfer namens **local**, hinter dem eine Engine auf diesem Rechner steht — Ollama, ein vLLM oder alles, was dieselbe OpenAI-kompatible Form spricht. Seine Modellauswahl ist das, was SIE installiert haben, mit Parametergröße, Quantisierung und Größe auf der Platte: was installiert ist, ist eine Tatsache über Ihren Rechner und keine Liste, die diese Erweiterung mitbringen könnte.",
    why: "Er kostet pro Runde nichts, und nichts verlässt das Haus. Damit ist er der Prüfer, den man sich bei jedem Push leisten kann — und der einzige für eine Änderung, die nirgendwohin geschickt werden darf. Er ist eine ANDERE Art Prüfer als die gehosteten, nicht eine billigere: das Panel gibt es, damit man mischt.",
    setup: "Über **＋ Add a model** auf **Models** hinzufügen — es läuft auf *der GPU dieses Rechners* —, und die Karte füllt sich selbst: die Engine wird auf 11434 (Ollama) und 8000 (vLLM) gesucht, und die Auswahl zeigt, was sie hat. Wird nichts gefunden, sagt die Karte, wo gesucht wurde und warum es nicht ging — abgelehnt, Zeitüberschreitung, seltsame Antwort — statt eine leere Liste zu zeigen.\n\nDas Endpunktfeld, unter **Connection**, ist für alles, was die Suche nicht sieht: ein vLLM auf einem anderen Port, ein Rechner im Netz, eine Engine hinter einem Proxy. Es will die OpenAI-kompatible Basis, endend auf `/v1` — **nicht** die Adresse, die man im Browser öffnet: Ollama bedient seine eigene API an der Wurzel und die kompatible unter `/v1`, und eine Basis ohne das scheitert bei der ersten Prüfung an einem 404, der wie ein Modellproblem aussieht.\n\n⟳ fragt die Engine erneut. Eine erfolgreiche Suche wird eine Minute zwischengespeichert, damit das Panel nicht bei jedem Neuzeichnen Modelle auflistet — ein gerade geholtes Modell ist also noch nicht da; genau dafür ist der Knopf.",
    usage: "**Geben Sie ihm Platz.** Eine Prüfung ist der Prompt, der Plan oder das Diff und das Schema, alles in einer Anfrage. Ein Modell mit kleinem Kontextfenster lehnt ab, statt schlecht zu antworten — ehrlich, und die Runde ist trotzdem verbraucht. Wo Sie die Wahl haben, nehmen Sie die Variante mit dem größeren Kontext.\n\nDiese Karte hat kein ▶ und kein ⤓, und ihr ⟳ ist kein Update, denn das sind die Knöpfe einer CLI: hier gibt es nichts anzumelden, zu installieren oder zu aktualisieren. Hier fragt ⟳ die Engine erneut, was sie hat, und ⇄ daneben erscheint nur im WSL-Fall unten. Token WERDEN gezählt — die Engine meldet sie und sie erscheinen in **What each AI has used** in **Show review rounds** — aber Geld ist ein Strich: ein Modell auf Ihrer eigenen Hardware hat keine Token-Rechnung. Es kostet Strom und eine belegte Karte, und beides sieht dieses Panel nicht.",
    whatCanGoWrong: "**Ein Endpunkt, der nicht auf diesem Rechner ist, wird auf der Karte angesagt, in Rot.** Jede Prüfung schickt den Prompt dorthin — Ihren Plan, Ihre Diffs und die Dateiinhalte drumherum. Genau dafür ist eine entfernte Engine da, und genau so verlässt Quelltext versehentlich das Haus, deshalb nennt die Karte den Host und was dorthin geht. Benutzen Sie nur einen, den Sie kontrollieren.\n\n**In einem an WSL angebundenen Fenster stehen einer Engine auf der Windows-Seite ZWEI Dinge im Weg.** Sie ist an `127.0.0.1` gebunden — starten Sie sie mit `OLLAMA_HOST=0.0.0.0`; und `127.0.0.1` auf dieser Seite ist WSLs eigenes Loopback, nicht der Windows-Host, also muss der Endpunkt auf die Adresse des Windows-Hosts zeigen. Antwortet die Engine von der Windows-Seite und diese Distribution erreicht sie nicht, bekommt die Karte ein ⇄ — **Switch WSL to mirrored networking** —, den anderen Ausweg: es zeigt Ihnen genau, was es schreiben wird, und schreibt dann `networkingMode=mirrored` in die Windows-`.wslconfig`; danach teilt WSL die Schnittstellen des Hosts, und `127.0.0.1` ist ohne weitere Einrichtung die richtige Adresse. WSL neu starten kann es nicht für Sie — das ist `wsl --shutdown` unter Windows, und es würde die Distribution beenden, in der diese Erweiterung läuft. Die Einstellung gilt für alle Distributionen, manche VPN-Clients vertragen sie nicht, und ein erneuter Druck auf ⇄ nimmt sie zurück.\n\n**Ein Modell, das die Engine nicht mehr führt,** bleibt mit *NOT on this engine any more* in der Liste — statt zu verschwinden (das würde Ihren Prüfer still austauschen) oder normal auszusehen (das würde eine Runde an ein Modell schicken, das 404 antwortet).",
  },
  "teach-your-ai": {
    title: "Und: Ihrer KI sagen, das Gate zu benutzen",
    whatItIs: "Das ⋯-Menü der ConnectOtherAIs-Seitenleiste → **Copy the CLAUDE.md snippet** liefert einen Absatz, der in das Repository kommt, das Sie reviewen lassen wollen. Er sagt der dort arbeitenden KI, dass es ein Review-Gate gibt, in welcher Reihenfolge es benutzt wird und dass ein DOKUMENT von einem eigenen Gate geprüft wird. Außerdem sagt er, wann `review_feature` aufgerufen wird — einmal, am Ende eines Plans mit 3 oder mehr Epics, vor dem Release — und dass ein `skipped` beim Feature-Review das Release nicht blockiert.",
    why: "Ein Assistent mit Werkzeugen, aber ohne Anweisung, kommt nicht von selbst darauf, eine Review-Sitzung zu öffnen. Dieser Absatz IST die Anweisung, und er lebt im Repository statt in der Erweiterung, weil er eine Eigenschaft des Projekts ist und nicht Ihres Editors.",
    setup: "Kopieren, in die `CLAUDE.md` jenes Repositories einfügen (oder in das, was Ihr Assistent liest), committen. Er nennt kein Repository: die KI, die ihn liest, sitzt ohnehin in einer Arbeitskopie, die sie selbst benennen kann.",
    usage: "Danach öffnet der Assistent eine Sitzung, schickt den Plan, arbeitet die Befunde ab, implementiert, schickt das Diff und arbeitet erneut ab. Sie sehen das unter **Active gates** und beantworten, was er eskaliert.",
    whatCanGoWrong: "Nichts erzwingt diesen Absatz. Der Assistent kann ihn ignorieren, und das Gate kann sich nicht selbst aufrufen. Was es KANN: sich weigern, Code zu reviewen, solange der Plan nicht durch ist — und das tut es.\n\n**Ein eingefügter Absatz veraltet still**, denn er lebt im Repository von jemandem, und diese Erweiterung entwickelt sich weiter. Der Tab **Setup › MCP server** der Settings liest den Absatz in diesem Arbeitsbereich und sagt es, wenn ihm ein Teil fehlt oder einer veraltet ist, wenn er älter ist als die Versionierung, oder wenn er NEUER ist als dieser Build — dann hat jemand das Repository aus einer neueren Erweiterung aktualisiert, und es ist dieser Build, der ein Update braucht. In den ersten beiden Fällen kopieren Sie ihn erneut und ersetzen den alten Block: was sich geändert hat, ist das, was der KI, die ihn liest, zu tun aufgetragen wird.",
  },
  "the-gate": {
    title: "Das Tor: Runden, die Schwelle, und was passiert, wenn sie aufgebraucht sind",
    whatItIs: "Drei Einstellungen, die entscheiden, wann eine Prüfung vorbei ist. **Rounds**, im Kasten jeder Rolle, ist, wie viele Versuche diese ROLLE bekommt. **Passes at or under**, daneben, ist, wie viele blockierende Befunde dieser Rolle hinnehmbar sind. **When the rounds run out**, in **Reviews › The gate**, ist, was passiert, wenn es nie dorthin kommt.",
    why: "Ohne Grenze endet eine Prüfschleife nie: es gibt immer noch einen Befund. Die Schwelle sagt als Zahl, was „gut genug“ heißt, bevor der Streit beginnt.",
    setup: "JEDE Rolle hat ihre eigenen Runden und ihre eigene Schwelle, eingestellt im Kasten dieser Rolle in **Reviews › Stages**: Architektur mag zwei Durchgänge mit verschiedenen Linsen wert sein, Performance nur einen, und ein gemeinsames Budget lässt die günstigste Rolle für die teuerste zahlen. Jede Code-Rolle hat zudem **einen Schalter**, ihr Häkchen **Active** in **Reviews › Roles & prompts**: nicht angehakt, nimmt die Rolle an der Runde überhaupt nicht teil — kein Prüfer wird für sie gestartet, nichts, was sie gefunden hätte, zählt, und sie leiht der Stufe weder ihre Runden noch ihre Schwelle; ihr Kasten in Stages sagt, wo ihr Schalter ist. Ihre Zahlen und Prompt-Auswahlen bleiben erhalten und kommen unverändert zurück, wenn Sie sie wieder ankreuzen. Die letzte lässt sich nicht ausschalten: eine Runde ohne jeden Prüfer wird nie aufgelöst. **Deal the lenses across vendors** steht ebenfalls in **Reviews › Stages**, auf der Plan-Stufe: aus — jeder Anbieter beantwortet dieselbe Frage, und die Übereinstimmung zweier Anbieter über einen Befund ist eine Tatsache, mit der das Tor arbeiten kann; ein — jede Linse wird einmal gefragt, bei halb so vielen Starts, und diese Übereinstimmung ist weg. Sein Zwilling auf der Code-Stufe ist **Deal the roles across vendors**: ein — jede Code-Rolle wird einem Anbieter gestellt statt allen, zum selben Preis an Übereinstimmung. Standard ist eine Runde für jede Rolle — zwei für das Feature-Review, dessen zweite Runde nur nach einem Prüferausfall, einem blockierenden Befund oder auf Ihren Wunsch läuft —, eine Schwelle von sechs für den Plan und fünf für jede Code-, Dokument- und Feature-Rolle, Verteilen aus, und *Ask a human*. Zur Schwelle zählen nur **blocking** und **major**; minor und nit blockieren nie.\n\nEin von zwei Anbietern erhobener Befund zählt EINMAL. Ein Befund, den Sie mit Begründung abgelehnt haben, zählt nicht wieder, bis ein Prüfer ihn mit einem wirklich neuen Argument erneut erhebt.",
    usage: "*Ask a human* ist die ehrliche Voreinstellung: das Tor hält an und legt die Entscheidung vor Sie. *Continue, and say so* macht weiter und sagt laut, dass Befunde offen bleiben — und rührt keinen davon an, genau so wird ein Tor zur Dekoration. *Good enough — take what’s true and move on* ist das Dazwischen: die KI liest die offenen Befunde, wendet die wahren und nützlichen an, lehnt den Rest mit Begründung ab und geht weiter. *Climb the ladder* eskaliert — mehr Prüferaufwand, dann ein stärkeres Prüfermodell, dann ein stärkerer Schiedsrichter — und gibt der Stufe jedes Mal einen frischen Satz Runden.\n\nDrei Schalter unter diesem Feld ändern nichts an dem, was das Gate ENTSCHEIDET — sie sind Anweisungen, die es der aufrufenden KI zurückgibt, und sie sind aus, bis Sie sie einschalten. **Work autonomously**: Der KI wird gesagt, was autonom BEDEUTET, nicht nur, es zu sein — jeder Fehler bekommt einen Red-Green-Red-Test; Dokumentation, README, Manifest und Moduldokumente werden mit jeder Änderung aktualisiert; vor einem Release laufen ALLE Tests; wo das Repository einen Release- oder Pull-Request-Prozess hat, wird er durchlaufen, und die automatischen Kommentare eines Pull Requests werden fünf Minuten später gelesen und behoben; ein automatisches Deploy wird gegen dev, stage oder test geprüft und seine Logs gelesen; der Code wird gegen die Regeln des Repositories nachgelesen; und die KI sagt, dass sie autonom arbeitet und was sie gerade schreibt. Fragen, die nicht blockieren, werden gesammelt und am Ende gemeinsam gestellt; eine blockierende sofort, aber erst nachdem alle weiteren blockierenden gesammelt sind — damit Sie einmal unterbrochen werden. **Split the plan into epics and stories**: Nach einem bestandenen Plan erfährt die KI, wie groß der Plan ist — nur Stories (3-5) oder 2-3, 3-4 bzw. 4-5 Epics aus Stories, weniger bei weniger Arbeit, nie mehr — und wie oft sie zum Tor zurückkehrt: einmal pro EPIC (jedes Epic auf eigenem Branch über dem vorigen, eine Plan-Runde, eine Code-Runde über seinen ganzen Diff, ein Commit) oder einmal für die GANZE Aufgabe (eine Code-Runde am Ende, weiterhin ein Commit pro Epic), gewählt unter dem Schalter. Nie pro Story. Das Gate misst den Plan, den Sie geschickt haben, sagt, ob er Epics, Stories oder nichts braucht, und sagt laut, dass das eine Heuristik ist. Die Anweisung ergeht einmal pro Assistent: Jedes Epic kommt für seine eigene Planprüfung zurück und hört, dass es ein TEIL ist — bau es als eine Einheit und schließe es sauber ab —, statt erneut zum Teilen aufgefordert zu werden, was kein Ende hätte. **Split with the strongest model**: Die Aufteilung selbst und die Stories, bei denen ein Irrtum teuer ist — Zahlungen, Sicherheit, Architektur —, gehen an das stärkste Modell des aufrufenden Assistenten, die gewöhnlichen an sein Umsetzungsmodell. Beide werden pro Art von Assistent direkt unter dem Schalter gewählt; für Claude Code sind es Fable und Opus, solange Sie nichts ändern, und ein Assistent ohne Auswahl soll sein eigenes stärkstes Modell nehmen, nicht das eines anderen Anbieters.\n\nEin weiterer Schalter steht über diesen drei, und er ist keine Anweisung — er ändert, wer prüft. **Stop the local reviewer when the cloud reviewers found almost nothing**: Haben alle Cloud-Prüfer geantwortet und zusammen höchstens eine Bemerkung gefunden, beendet der lokale Prüfer seinen laufenden Start und beginnt keinen weiteren — die Runde nennt, was sie nicht gestartet hat, und warum. Ein fehlgeschlagener Cloud-Prüfer hält ihn am Laufen. Eine Runde liest den Schalter beim Start, eine Änderung gilt also ab der nächsten Runde.",
    whatCanGoWrong: "Eine Schwelle von null heißt, dass jeder Befund jeder Schwere blockiert, was in der Praxis heißt, dass eine Prüfung nie besteht.\n\nRunden gelten pro ROLLE: jede Rolle bekommt ihre eigene volle Zahl, und ein Befund zählt gegen die Schwelle der Rolle, die ihn erhoben hat, sodass eine laute Rolle nicht die Toleranz einer anderen verbrauchen kann. Eine Stufe besteht, wenn jede Rolle auf oder unter ihrer eigenen Zahl liegt.",
  },
  "the-gates-commands": {
    title: "Die Befehle des Tors, in Ihren Worten",
    whatItIs: "**Reviews › Commands** in den Settings zeigt jeden Satz, aus dem die Anweisungen des Tors bestehen — Autonomie, die Aufteilung, der Takt des Tors, die Modell-Anweisung — und lässt Sie eigene an ihre Stelle schreiben; **Edit commands…**, in **Reviews › The gate**, springt dorthin. Unter **Yours** fügen Sie mit **Add a command** eigene Befehle hinzu: jeder mit Titel, den Runden, in denen er gegeben wird (jede Runde, Plan- oder Code-Runden), einem Schalter und dem Text, den er der KI sagt. Unter **Shipped** stehen die eigenen Worte der eingebauten Anweisungen.",
    why: "Die Anweisungen sind Worte, nach denen eine KI handelt, und ein Team hat seine eigenen: eine Hausregel, eine Checkliste, ein Satz, der ein Modell vom Abkürzen abhält. Ein Wort einer ausgelieferten Anweisung zu ändern war bisher ein Release.",
    setup: "Schreiben Sie in ein Feld, um einen ausgelieferten Text zu ersetzen; ein leeres Feld ist der ausgelieferte Text, blass angezeigt. **Restore the shipped text** löscht Ihren. Stehen vor einem Feld Worte in **fett**, behält der Server sie, was immer Sie schreiben — an ihnen wird eine Anweisung als gegeben erkannt. Namen in geschweiften Klammern wie `{scope}` oder `{strongest}` füllt der Server aus.",
    usage: "Ihre eigenen Befehle bekommt die KI nach den eingebauten Anweisungen. Einer lässt sich erst einschalten, wenn er Text hat, und ein neuer beginnt ausgeschaltet. Einen Befehl zu entfernen entfernt auch seinen Text. Alles wird beim Tippen gespeichert, im selben Datenordner wie Ihre Prompts, also nimmt Export config es mit.",
    whatCanGoWrong: "Ein Server älter als 0.33.0 ignoriert all das und gibt die ausgelieferten Anweisungen; **Reviews › Commands** sagt es ganz oben. Ein eingeschalteter Befehl ohne Text — von Hand in den Einstellungen geschrieben — bleibt aus der Runde heraus, und die Antwort nennt die Datei, die zu schreiben ist.",
  },
  "prompts-per-round": {
    title: "Prompts pro Runde: welche Frage jede Runde stellt",
    whatItIs: "Jede Prüferrolle hat einen universellen Prompt und fünf enge Linsen. **Reviews › Prompts per round** wählt, welchen Prompt jede RUNDE dieser Rolle nutzt, ein Wähler für jede Runde, die die Rolle hat. Wie viele Runden eine Rolle bekommt, und ihre Schwelle, werden daneben in **Reviews › Stages** eingestellt, weil diese drei Einstellungen gemeinsam eine Frage beantworten.\n\nDie letzten zwölf Linsen wurden gemessen, bevor sie ausgeliefert wurden: je drei Formulierungen, je zwei Läufe. Die drei Formulierungen erwiesen sich als drei FORMEN, und sie finden gleich viel — sie unterscheiden sich darin, wie viel einen zweiten Lauf übersteht: eine als Aufgabe geschriebene Linse (*„führe es zweimal aus, eine Millisekunde versetzt, und schildere beide“*) wiederholt sich um die Hälfte häufiger als dieselbe Frage als Prüfliste.",
    why: "Ein Prompt pro Rolle für immer ist die richtige Voreinstellung und die falsche Obergrenze. Wird ein Modell gebeten, auf alles zu schauen, verteilt es sich dünn, und eine zweite Runde derselben breiten Frage gibt meist dieselben breiten Antworten.",
    setup: "Ein Wähler pro Runde pro Rolle; jede Option trägt ihren Zweck als Tooltip. Eine Runde, die Sie nicht angefasst haben, zeigt, was der Server für sie wirklich starten wird — der Wähler ist nie eine Vermutung und nie ein Prompt, den niemand ausführt.\n\n**Conventions ist eine eigene Code-Rolle, mit einem Prompt.** Sie beurteilt das Diff nach den Regeln, die dieses Projekt aufgeschrieben hat — `CLAUDE.md`, `AGENTS.md`, `GEMINI.md`, `.claude/rules` — und nach nichts sonst, und ein Befund muss dort den Satz zitieren, den er bricht. In einem Repository ohne Regeldateien werden ihre Prüfer gar nicht erst gestartet, denn ein Konventionsdurchgang ohne Konventionen hat nichts zu sagen. Die anderen Code-Rollen verwenden jede Runde auf ihr eigenes Thema.\n\nJede ungesetzte Runde ist die universelle Frage dieser Rolle. Eine Linse wird gestellt, wenn Sie sie stellen: eine automatische Rotation gibt es nicht mehr. Es gab eine, sie hatte keinen Schalter, den das Panel erreichen konnte, und ihre einzige verbliebene Wirkung war, dass dieser Wähler einen Prompt nannte, den der Server nicht ausführt.\n\n**Die Überschrift der Code-Stufe in Reviews › Stages rechnet laut vor** — *2 vendors × up to 4 roles = 8 reviewers per round, each runs once per round, up to 1 round* — und zählt nur die Anbieter und Rollen, die eingeschaltet sind. *Up to*, weil die Conventions-Prüfer in einem Repository ohne aufgeschriebene Regeln übersprungen werden und das Panel das nicht wissen kann, bevor die Runde nachsieht. Darunter ist **What a reviewer gets** der andere Schalter der Code-Stufe: **Fast — diffs only** oder **Full — with the code**. *Unter der Haube: wo ein Reviewer wirklich läuft* sagt, was jede Variante kostet und warum Fast die Voreinstellung ist.\n\nAuf die Code-Stufe folgen zwei weitere Gruppen. **Document stage** enthält die Rollen, die `review_document` über ein DOKUMENT statt eines Diffs ausführt — *The document* und *Summary* werden dort mitgeliefert —, jede mit ihren eigenen Wählern hier, ihren Runden und ihrer Schwelle in Stages und ihrem Schalter in **Reviews › Roles & prompts**. **Feature stage** enthält die Rolle, die `review_feature` einmal ausführt, am Ende eines Plans mit drei oder mehr Epics, über das ganze Feature. Ihr Häkchen **Active**, in Roles & prompts, ist der eigene Schalter des Feature-Gates: nicht angehakt, hält das Gate fest, dass das Feature-Review nicht lief, und blockiert nicht. Welche Modelle ein Feature prüfen, bestimmt das Häkchen **reviews features** auf jeder Karte in Models.",
    usage: "**Deal the lenses across vendors**, auf der Plan-Stufe, und **Deal the roles across vendors**, auf der Code-Stufe, sind die Schalter in **Reviews › Stages**, und sie sind es, die ändern, wie eine Runde ausgegeben wird: aus — jeder Anbieter beantwortet jede Frage dieser Runde; ein — die Prompts der Runde, auf der Code-Stufe ihre Rollen, werden über die Anbieter verteilt, sodass jede Frage einmal gestellt wird statt einmal pro Anbieter. Bezahlt wird mit Übereinstimmung: zwei Anbieter, die denselben Befund melden, sind das stärkste Signal dieses Produkts, und eine verteilte Runde kann es nicht erzeugen. Genau deshalb sind sie standardmäßig aus.\n\nWollen Sie zwei verschiedene Linsen auf einer Änderung, setzen Sie sie auf zwei Runden und lassen beide laufen. Es wurde gemessen: über zwei Code-Runden fand das Ausgeben an verschiedene Linsen WENIGER verschiedene Befunde als zweimal die universelle Frage (17 gegen 25), für weniger Geld — weshalb es niemand für Sie tut.\n\nDen vollen Text jedes Prompts finden Sie in **The prompts, in full**.",
    whatCanGoWrong: "**Was die Messung NICHT belegt.** Über drei Pläne fand die Vereinigung dreier Linsen etwa doppelt so viel wie jede einzelne — und dieses Ergebnis übersteht seine eigene Kontrolle nicht: DERSELBE Prompt auf DEMSELBEN Text ergab dreimal 6, 4 und 5 Befunde mit Überschneidungen von 3, 1 und null. Streuung zwischen Läufen allein erklärt die Spanne. Die Linsen werden angeboten, weil man mit ihnen nützlich zielt, nicht weil gezeigt wurde, dass sie mehr finden.",
  },
  "limits": {
    title: "Grenzen: wie viele gleichzeitig und wie lange auf jeden gewartet wird",
    whatItIs: "**Reviewers at once** begrenzt den ganzen Fächer. **Per vendor** begrenzt einen Hersteller. **Reviewer timeout** — wie lange ein Reviewer laufen darf. **Round limit** — wie lange sie alle zusammen bekommen. **Wait for you** — wie lange eine Eskalation auf einen Menschen wartet, bevor sie aufgibt.",
    why: "Eine Code-Runde mit zwei Herstellern sind acht Prozesse, die in derselben Sekunde starten wollen: die vier mitgelieferten Code-Rollen mal zwei Hersteller. Ohne Grenze treffen genau hier Prozesslimits des Systems, die Lock-Dateien der CLIs und die Herstellerlimits gleichzeitig ein — und jedes sieht aus wie ein Timeout, solange es nicht beim Namen genannt wird.",
    setup: "Voreinstellung: drei gleichzeitig, zwei je Hersteller. Die Grenze je Hersteller existiert, weil ein Ratenlimit pro Hersteller gilt: eine einzige gemeinsame Grenze würde alle Plätze bereitwillig an einen vergeben.\n\nDas Reviewer-Timeout sind zehn Minuten. Eine Code-Runde auf einem großen Diff braucht drei bis fünf.\n\nDas Round limit begrenzt eine ganze Runde statt eines einzelnen Reviewers, und es steht standardmäßig auf 0 — das heißt, es wird ausgerechnet statt geraten. Eine Runde schickt Ihre Hersteller mal ihre Rollen durch die Grenze oben, braucht also so viele Wellen, wie diese Division ergibt, und jede Welle darf ehrlich ein volles Reviewer-Timeout dauern: drei Hersteller, vier Code-Rollen und eine Grenze von drei sind vier Wellen, vierzig Minuten. Setzen Sie eine Zahl, überschreiben Sie das. Setzen Sie eine kleine, schneiden Sie in Reviewer, die noch nicht fertig sind — sie werden abgebrochen, ihre Befunde gehen verloren, und die Runde wird ohne sie entschieden.",
    usage: "Erhöhen Sie die gemeinsame Grenze auf einer Maschine mit freien Kernen und senken Sie sie auf dem Notebook, auf dem Sie nebenher arbeiten. Wer in Herstellerlimits läuft, senkt die Grenze JE HERSTELLER.",
    whatCanGoWrong: "Das Timeout tötet den ganzen Prozessbaum, nicht nur die CLI: die Kindprozesse eines Reviewers überleben ihn nicht.\n\nDas Ablaufen von **Wait for you** ist keine Absage: die Eskalation bleibt im Panel offen, und die KI wird angewiesen, Sie im Gespräch zu fragen.",
  },
  "language-and-translator": {
    title: "Sprache: die Fragen sind englisch",
    whatItIs: "Hier gibt es nichts mehr einzustellen. Eine `call_human`-Frage erreicht Sie als ein fester englischer Satz mit drei Knöpfen, und Ihre Antwort geht genau so zurück, wie Sie sie gegeben haben.",
    why: "Es gab einmal einen Übersetzer: die Frage war Prosa, die eine KI geschrieben hatte, Sie mussten sie lesen, und Sie antworteten in eigenen Worten. Drei Knöpfe haben all das entfernt. Ein Unterprozess pro Eskalation, der ablaufen, verweigern oder in der falschen Sprache antworten kann, ist ein bewegliches Teil, das nichts verdient.",
    setup: "Nichts. Die Bedienelemente **Ask and answer in** und **Translated by** sind fort, mit ihnen die Einstellungen `COAI_LANGUAGE` und `COAI_TRANSLATOR_*` dahinter.",
    usage: "Die Sprache DIESER Hilfe ist getrennt und weiterhin Ihre: der Wähler oben auf diesen Seiten schaltet sie um, gespeichert als `coai.helpLanguage`. Geändert hat sich die Prüferseite, nicht die Leseseite.",
    whatCanGoWrong: "Hier kann nichts mehr scheitern, was der Punkt war. Tippen Sie Freitext auf einem Knopf, der das anbietet, erreicht er die KI unvermittelt — mehr wert als dieselben Worte, von einem dritten Modell in eine andere Sprache gebracht.",
  },
  "vendor-keys": {
    title: "Hersteller-Schlüssel: nur, wenn eine CLI sich nicht selbst anmelden kann",
    whatItIs: "Ein einzelner `config`-Eintrag in CredsForDevs, der je einen Schlüssel für jeden Hersteller hält, der einen braucht. **Setup › Vendor keys** zeigt, welches Ihrer Modelle ihn wirklich benötigt — jedes Modell auf Models, nicht nur die Reviewer —, und darunter listet **CLIs your models run on** jede CLI einmal, mit ihrer Version und ihrem ▶ ⤓ ⟳.",
    why: "Die meisten Reviewer-CLIs sind auf Ihrer Maschine bereits angemeldet und brauchen gar keinen Schlüssel. Wer einen braucht — ein eigener Endpunkt, DeepSeek, OpenRouter — sollte ihn nicht in eine Einstellungsdatei tippen.",
    setup: "Nur nötig, wenn **Setup › Vendor keys** sagt, dass eines Ihrer Modelle einen Schlüssel braucht. Legen Sie in CredsForDevs einen `config`-Eintrag an, hinterlegen Sie die Schlüssel als `{\"deepseek\": \"sk-…\"}` und tragen Sie dessen Kennung unter **CredsForDevs config key** ein.",
    usage: "Der Server liest den Eintrag beim Start und reicht jeden Schlüssel über die Umgebung an seinen Hersteller weiter, nie über die Kommandozeile. Ein gewechselter Schlüssel gilt ab dem nächsten Serverstart.",
    whatCanGoWrong: "Ein Hersteller, der einen Schlüssel braucht und keinen hat, erscheint in **providers** als `unavailable` mit Grund und fällt aus dem Fächer — er wird nicht stillschweigend übersprungen.",
  },
  "team-servers": {
    title: "Team servers: Reviewer auf dem Abonnement der Firma",
    whatItIs: "**Setup › Team servers** in den Settings listet die Team server, die dieser Rechner kennt, je einer pro Zeile, und **＋ Add a Team server** fügt einen weiteren hinzu. Eine Zeile besteht aus Name und Adresse des Servers, dem Konto, mit dem Sie angemeldet sind — oder *no account* —, einem Satz, der sagt, wie es steht, wie viele Konten jeder seiner Anbieter frei hat, einer Zeile, die den Host nennt, an den jedes dorthin geschickte Review geht, und zwei Schaltflächen: **Sign in** oder **Sign out**, und **Remove**.",
    why: "Ein Team server führt die Hersteller-CLIs auf einem Rechner aus, auf einem Firmenabonnement, sodass niemand ein eigenes Abonnement braucht. Alles, was Sie wissen müssen, bevor Sie ihm ein Review anvertrauen — wer Sie für ihn sind, ob er läuft, ob er ein Konto frei hat und wohin Ihr Code geht —, ist eine Eigenschaft dieses Servers und nicht eines einzelnen Modells. Deshalb wird es einmal gesagt, hier, statt auf jeder Karte in Models wiederholt zu werden.",
    setup: "**＋ Add a Team server** fragt nach zwei Dingen: einem kurzen Namen, der Ihnen gehört und nur der Anzeige dient, und seiner Adresse. Dann drücken Sie **Sign in** und melden sich mit Ihrem Arbeitskonto an; währenddessen sagt die Zeile *Signing in…*, und ihre Schaltflächen sind gesperrt, damit eine langsame Anmeldung nicht für eine gehalten wird, die nichts getan hat. Sobald Sie angemeldet sind, fragt die Zeile den Server, was er anbietet, und seine Anbieter erscheinen in **＋ Add a model** auf Models.",
    usage: "**Der Satz unter dem Konto sagt, wie es steht.** *Not signed in.* ist der schlichte Fall. *<account> is signed in on another side of this machine — press Sign in to use it here* heißt, dass zum Beispiel ein Windows-Fenster und ein WSL-Fenster offen sind und diese Seite sich noch nicht selbst angemeldet hat. *Signed in. Asking what it offers…* wird zu *Signed in. Server <version>.*, sobald er geantwortet hat. Ein Problem wird in den eigenen Worten des Servers gesagt, und zeigt die Zeile eine ältere Antwort, endet sie mit *— showing what it last said*.\n\n**Eine Zeile pro Anbieter zählt seine Konten**: *codex: 2 of 3 ready, 1 cooling down*; *no accounts — ask the operator*; *all 3 signed out — the operator must sign them in*; *all 3 rate-limited, they come back by themselves*. Das ist der Unterschied zwischen einem Warten und einem Fehler, bevor eine Runde es für Sie herausfindet.\n\n**Sign out** beendet Ihre Sitzung auf dem Server. **Remove** fragt vorher: es meldet Sie ab, löscht das Token von diesem Rechner und vergisst den Server, und laufen noch Modelle auf Models über ihn, nennt es sie und bietet **Remove it and N reviewers** oder **Remove the server only** an — ihre Ausgabenhistorie bleibt in beiden Fällen erhalten.\n\nEin Administrator des Servers sieht eine Zeile mehr: welches Team-server-Release veröffentlicht ist und ob dieser es ausführt. Es gibt keine Update-Schaltfläche, und es kann keine geben — ein Team server wird auf seinem eigenen Rechner bereitgestellt, nicht auf diesen heruntergeladen. Was ein Team server ausgegeben hat, steht in **What each AI has used**, in einem eigenen Block.",
    whatCanGoWrong: "**Jedes an einen Team server geschickte Review verlässt diesen Rechner**, und die Zeile sagt das in einem Satz, der den Host nennt — Ihr Plan, Ihre Diffs und die Dateiinhalte drumherum. Dass es der eigene Server der Firma ist, macht das nicht weniger wahr.\n\n**Eine Warnung, dass der Server eine ältere Version der API spricht,** heißt, dass diese Erweiterung einen neueren Team server braucht als den, der antwortet. Es ist eine Warnung und keine Ablehnung — Reviews gehen weiterhin durch —, aber die eine Hälfte kann die andere falsch lesen, und die Abhilfe ist ein Update des Team servers, was Sache seines Betreibers ist.\n\nEinen Server zu entfernen entfernt die Modelle, die über ihn laufen, nur dann, wenn Sie das wählen; ein Modell, das auf einen verschwundenen Server zeigt, kann nur scheitern. Schlägt die Abmeldung fehl, erfahren Sie es, und das Entfernen läuft weiter: eine Token-Datei, die ein Entfernen überlebt hat, ist ein Zugang, auf den niemand achtet.",
  },
  "bugz": {
    title: "Bugz: die Fehler, die Ihr Gate bereits gefunden hat",
    whatItIs: "Jeder ANGENOMMENE Befund ist ein Fehler, den ein Mensch bestätigt hat. **Bugz** liest sie als Material zurück, nicht als Protokoll: es findet die Methode, um die es ging, findet den Commit, der sie behoben hat, und behält das Paar. **Collect** sucht; **Review bugs** ist der Ort, an dem Sie entscheiden, was bleibt.",
    why: "Ein Review-Gate erzeugt etwas, das die meisten Werkzeuge wegwerfen: Paare von Code, der falsch war und dann richtig, jedes von einem Menschen bestätigt statt geraten. Gemessen an einer echten Datenbank am 15.09.2026 — 8 687 Befunde verengen sich auf 462 brauchbare über 115 Stories und 15 Repositories.\n\n**Gelesen wird nur, was ohnehin auf Ihrer Maschine liegt.** Die Befunde stammen aus Ihren eigenen Runden, der Code aus Ihrer eigenen git-Historie. Das Sammeln sendet nichts irgendwohin.",
    setup: "Wählen Sie ein **Ranking-Modell** — angeboten werden nur Engines, die auf dieser Maschine laufen, und das ist eine Entscheidung, keine Vorsicht: Titel und Beschreibung eines Befundes sind die eigenen Worte der Reviewer über Ihren Code, und sie sind NICHT anonymisiert. Die Anonymisierung läuft später und nur über Quelltext. Dieser Schritt liest sie also hier — oder gar nicht.\n\nDann **Collect** drücken. Der Abschnitt zeigt den Lauf, während er läuft, und am Ende, was aus jedem Kandidaten wurde.",
    usage: "Ein Lauf entscheidet jeden unbearbeiteten Befund und schreibt auf, was er entschieden hat: **collected** mit dem behebenden Commit, **skipped** mit einem Grund, oder **failed**. Skipped ist gewöhnlich — eine Sprache, die hier niemand parst; ein Commit, den kein Branch mehr erreicht; eine Behebung, die nicht in diesem Repository liegt — und der Grund bleibt erhalten, damit die Quote eine Messung ist und kein Achselzucken.\n\nDer Lauf wird erinnert; das Fenster zu schließen oder F5 zu drücken ändert, was Sie SEHEN, und nie, was geschehen ist. Drücken Sie später wieder Collect, und er nimmt die, die noch niemand angesehen hat.\n\n**Who holds a key** ist die andere Hälfte: die Beitragenden-Schlüssel, die Ihr Ingest-Server ausgegeben hat, was jeder gesendet hat, und die Schaltfläche, die einen beendet. Führen Sie zuerst **Set the bugs admin key** aus — er liegt im Secret Storage des Editors auf diesem Rechner, nie in den Einstellungen: Einstellungen synchronisieren, und ein Administrationsschlüssel, der Ihnen auf einen anderen Rechner folgt, ist einer, für den niemand geradesteht.\n\nEin Schlüssel wird EINMAL angezeigt, bei der Ausgabe. Schließen Sie das Fenster, bevor Sie ihn kopiert haben, bietet ihn der Tab beim nächsten Öffnen erneut an und kann ihn für Sie widerrufen — der Server zeigt ihn kein zweites Mal. Das Widerrufen fragt vorher und nennt die Notiz des Schlüssels und den Monat der letzten Nutzung, denn die Kennungen sind hexadezimal und sehen einander ähnlich.\n\n**Send** ist der letzte Schritt — und der, den dieser Abschnitt bisher gar nicht konnte: er lädt die von Ihnen behaltenen Paare hoch, über denselben Einmal-Modus, den jemand früher von Hand im Terminal aufrief. Führen Sie zuerst **Set the bugs contributor key** aus — ein anderer Schlüssel als der Administrationsschlüssel, am selben Ort und aus demselben Grund verwahrt.\n\nJeder Schlüssel wird unter dem Ingest-Server abgelegt, zu dem er gehört; eine Seite, die einen anderen Server nennt, hat also keinen Schlüssel, bis Sie dort einen setzen. Schlüssel, die gespeichert wurden, bevor Schlüssel je Server abgelegt wurden, liegen beiseite und werden nirgendwohin gesendet: **Settle old Bugz keys** übernimmt sie für den Server dieser Seite — nur wenn dieser sie ausgestellt hat — oder verwirft sie.\n\n**Wohin die Paare gehen** ist die letzte Schaltfläche des Abschnitts. **Set the ingest server…** fragt nach der Adresse des Bug-Ingest-Servers; ist eine gesetzt, lautet die Schaltfläche **Ingest server: <address>**, sodass das Ziel bei jedem Druck auf Send auf dem Bildschirm steht, und ein Druck darauf ändert es. Eine leere Adresse sendet nirgendwohin.\n\nEin Paar gilt erst dann als gesendet, wenn der Server sagt, dass er es hat; ein abgebrochener Sendelauf verliert daher nichts: drücken Sie erneut Send, und die bereits angekommenen werden erkannt statt ein zweites Mal gespeichert. Während eines Laufs sagt die Schaltfläche das — auch nach einem Neuladen, denn der Lauf steht dort geschrieben, wo beide Hälften ihn sehen.\n\n**Review checkouts on this machine** ist ein Befehl in der Palette und die andere Hälfte der Schaltfläche *Check out <sha> in a new window* in einer Zeile. Er listet jedes Checkout auf, das diese Schaltfläche hier angelegt hat — welches Repository, welcher Commit, wann, und ob es noch brauchbar ist —, öffnet jedes davon und gibt eines zurück.\n\nEine Entfernung wird ABGELEHNT, mit Namen, wenn im Checkout etwas von Ihnen liegt: eine geänderte Datei, eine nie committete Datei, oder beides innerhalb eines Submoduls — was ein einfaches status zwar sieht, aber nie benennt. Ignorierte Dateien sind der Fall, mit dem niemand rechnet (`.env`, eine lokale Konfiguration): sie werden gezählt, einige gezeigt, und sie gehen nur mit, wenn Sie ein zweites Mal fragen.\n\n**CoAI: choose** in jeder Zeile legt dieses Paar in einen Chat — Where, Why, Fix, Complexity, Before, After und Ihren Kommentar, auch den noch nicht gespeicherten — und sendet nichts: Modell und Frage wählen Sie im Chat, wie nach *CoAI: choose* per Rechtsklick. Jeder Fehler bekommt eine eigene Unterhaltung mit dem Namen seiner Methode; ein zweiter Druck holt sie zurück, ohne anzutasten, was Sie dort schon zu schreiben begonnen haben.\n\n**Jede Zeile in Before und After ist nummeriert.** Ein Skelett zählt ab der ersten Zeile seiner Methode, weil nur die Methode aufbewahrt wurde; der echte Code zählt, wie seine Datei in diesem Commit. Die Nummer und das +, − oder ~ daneben werden gezeichnet, nicht in den Code geschrieben — eine Kopie des Codes enthält also nur den Code.",
    whatCanGoWrong: "**Ein unterbrochener Lauf sagt das auch.** Schließen Sie das Fenster mittendrin, hört die Zeile auf zu melden, dass sie lebt; beim nächsten Nachfragen wird sie als unterbrochen markiert, statt weiter laufend auszusehen. Was bereits entschieden war, bleibt: jeder Kandidat wurde geschrieben, sobald er entschieden war.\n\n**Mehr als die Hälfte der Commits ist unerreichbar, und das ist normal.** Squash-Merge löscht den Branch, auf dem eine Runde lief — 55,7 % der gemessenen Kandidaten — aber die Objekte überleben, also lässt sich die Methode weiterhin lesen und die Suche weiterhin durch die nächste Runde derselben Sitzung begrenzen.\n\n**Ein nicht lokales Modell wird abgelehnt, woher es auch kommt.** Das Panel bietet keines an, und der Collector lehnt es ohnehin ab, bevor er einen einzigen Befund liest — eine Auswahlliste ist keine Garantie.",
  },
  "review-bugs-page": {
    title: "Die Seite Review bugs: behalten, verwerfen und den Code lesen",
    whatItIs: "**Review bugs**, im Abschnitt Bugz der Seitenleiste, öffnet eine Seite mit jedem Paar, das Collect erzeugt hat: eine Zeile pro Methode, eingeklappt, mit Schwere, Kategorie, Titel und Ihrer bisherigen Entscheidung — *undecided*, *kept* oder *dropped*. Die Zeile darüber sagt, wie viele noch auf Sie warten. Aufgeklappt zeigt eine Zeile, wo der Befund war und was die Reviewer gesagt haben, den Code Before und After, die Schaltflächen, die diesen Code öffnen, und **Your comment on this pair**.",
    why: "Ein Paar wird nur gesendet, wenn ein Mensch es behalten hat, und ein Mensch kann nur behalten, was er gelesen hat. Zweihundert Paare, jedes mit zwei Skeletten, sind eine Seite, die niemand durchscrollt — deshalb zeigt die Seite zuerst die LISTE und den Code, wenn Sie danach fragen, und jeder Weg zur echten Datei sagt, welche Revision es ist.",
    setup: "Nichts einzurichten. Die Schaltfläche ist gesperrt, bis Collect mindestens ein Paar erzeugt hat. **Which project** und **Which language**, über der Liste, grenzen sie auf je eines ein.",
    usage: "**Zeilen anhaken, dann gemeinsam entscheiden.** **Keep selected** und **Drop selected** entscheiden jede angehakte Zeile, **Clear selection** hakt alle ab, und das Kästchen in der Kopfzeile hakt jede Zeile an. **Expand all** und **Collapse all** klappen jede Zeile auf und zu; ein Klick auf die Kopfzeile eines Eintrags öffnet genau diesen.\n\n**Real code** schaltet Before und After von den anonymisierten Skeletten auf die Methoden, wie sie wirklich sind. Das ist nur eine Ansicht: gesendet wird das Skelett, was immer dies zeigt.\n\n**Drei Wege zum Code, und jeder sagt, welcher Code es ist.** **Open at <sha>** öffnet die Datei, wie sie in dem Commit war, den die Reviewer gelesen haben, nur lesbar, direkt aus git — auch wenn kein Branch diesen Commit mehr erreicht, was nach einem Squash-Merge der übliche Fall ist. **Open CURRENT (may differ)** öffnet die Datei, wie sie jetzt in Ihrem Arbeitsbaum ist — dort, wo eine Korrektur gemacht würde, und womöglich nicht mehr der Code, den die Reviewer gelesen haben. **Check out <sha> in a new window** checkt das ganze Repository in diesem Commit in einen eigenen Ordner aus; das ist langsamer, denn es ist ein echtes Checkout, und das erste holt auch die Submodule. **Who calls this?** fragt die Sprachunterstützung, wer die Methode aufruft und was sie aufruft — im CURRENT-Checkout, was die Schaltfläche sagt, bevor Sie sie drücken, denn die Zeile handelt von dem Commit, den die Reviewer gelesen haben.\n\n**Your comment on this pair** reist mit dem Paar: er wird mit ihm an den Corpus-Server gesendet, öffentlich und nicht anonymisiert, genau so, wie Sie ihn getippt haben, bis zu tausend Zeichen. Sobald der Server das Paar hat, ist das Feld nur noch lesbar und sagt, wann es gesendet wurde.",
    whatCanGoWrong: "**Eine Seite, die die Paare nicht lesen konnte, sagt das**, mit dem Grund des Servers, und *Nothing has been collected yet* bedeutet etwas anderes — drücken Sie Collect. Die beiden schicken Sie an verschiedene Stellen, und deshalb sind sie nie derselbe Satz.\n\n**Ein Kommentar ist öffentlich.** Er ist das Einzige auf dieser Seite, das so gesendet wird, wie Sie es geschrieben haben, statt anonymisiert, und die Zeile unter jedem Kommentarfeld sagt das. Ein Kommentar, den der Server nach dem Senden des Paares nicht gespeichert hat, wird an der Zeile benannt, mit dem Grund.\n\n**Open at <sha>** wird nicht angeboten, wenn der Commit oder die Datei darin nicht gelesen werden kann, und die Zeile sagt daneben, warum, statt eine Schaltfläche anzubieten, die nichts öffnet.",
  },
  "who-holds-a-key": {
    title: "Who holds a key: die Beitragenden-Schlüssel, die Ihr Ingest-Server ausgegeben hat",
    whatItIs: "**Who holds a key**, im Abschnitt Bugz der Seitenleiste, öffnet eine Seite mit den Beitragenden-Schlüsseln, die Ihr Ingest-Server ausgegeben hat: die Notiz jedes Schlüssels, seine Kennung, wann er zuletzt benutzt wurde, wie viele Paare er gesendet hat und wie viele warten, und **Revoke** an jedem Schlüssel, der noch gilt. Über der Liste: **Issue a key**, **Refresh**, sowie **Back** und **Next** zum Blättern.",
    why: "Mit einem Beitragenden-Schlüssel kann jemand Paare an Ihren Corpus senden. Ein Schlüssel, für den niemand geradestehen kann, ist eine Tür, auf die niemand achtet — deshalb beantwortet die Seite, wer einen hält, was jeder gesendet hat, und beendet einen mit einem Druck.",
    setup: "Führen Sie zuerst **Set the bugs admin key** aus. Er liegt im Secret Storage des Editors auf diesem Rechner, nie in den Einstellungen: Einstellungen synchronisieren, und ein Administrationsschlüssel, der Ihnen auf einen anderen Rechner folgt, ist einer, für den niemand geradesteht. Ohne ihn sagt die Seite das und bietet dieselbe Schaltfläche an.",
    usage: "**Issue a key** fragt, wofür der Schlüssel ist — Ihre Notiz, warum es ihn gibt, *the tuesday workshop*, nie Name oder Adresse des Inhabers — und zeigt den Schlüssel dann EINMAL. **Copy the key** legt ihn in Ihre Zwischenablage. **Discard and revoke it** ist für einen Schlüssel, den Sie doch nicht herausgeben: es widerruft ihn auf dem Server, sodass kein Schlüssel gültig bleibt, den niemand hält.\n\n**Revoke** fragt vorher und nennt die Notiz des Schlüssels und den Monat der letzten Nutzung, denn die Kennungen sind hexadezimal und sehen einander ähnlich.",
    whatCanGoWrong: "**Ein ausgegebener und nie kopierter Schlüssel bleibt auf dieser Seite**, über der Liste, bis Sie ihn kopieren oder verwerfen — der Server zeigt ihn kein zweites Mal. Hat sich ein Fenster geschlossen, nachdem der Server einen Schlüssel erzeugt hatte und bevor dieser Rechner davon erfuhr, sagt die Seite, dass ein Schlüssel ausgegeben worden sein *kann*: sie kann ihn nicht zeigen, er wäre die neueste Zeile, und diese Zeile zu widerrufen ist der Weg, sicherzugehen, dass niemand einen Schlüssel hält, den Sie nicht haben. **I have checked the list** schließt diesen Hinweis.\n\nEin Schlüssel, der nicht angenommen wird, wird nicht diagnostiziert: der Server beantwortet einen falschen Schlüssel, einen widerrufenen Schlüssel und einen Server ohne Administratoren absichtlich gleich, also kann die Seite Ihnen nicht sagen, welcher Fall es ist — prüfen Sie den hier hinterlegten Schlüssel und das Startprotokoll des Servers. Ein Server, der nicht erreichbar war, und einer, der Sie drosselt, sagen das jeweils und bieten **Try again** an; nichts wird von selbst wiederholt. Eine Anfrage, die der Server abgelehnt hat, bietet **Back to the newest** an — dort fangen Sie wieder an, wenn Sie geblättert haben. Ein Ingest-Server, an den diese Seite keinen Administrationsschlüssel schickt, wird abgelehnt, bevor irgendetwas gesendet wird, und die Seite sagt, dass der Schlüssel nirgendwohin ging — ändern Sie den Ingest-Server im Abschnitt Bugz und öffnen Sie die Seite erneut.",
  },
  "recent-rounds": {
    title: "Active gates, Active consultations und Consultation cadence: was gerade läuft",
    whatItIs: "Drei Abschnitte der Seitenleiste, einer unter dem anderen. **Active gates** ist jede laufende Runde, neueste oben, vollständig: was reviewt wird, die Stufe, der Branch, wie lange sie schon läuft — und darunter jeder Reviewer, den die Runde gestartet hat, mit dem, was er bisher getan hat, wie viele Funde er eingereicht hat, wie lange ER gebraucht hat und was er gelesen hat. **Active consultations** ist jede Konsultation, die gerade geführt wird. **Consultation cadence** zeigt, wo jeder Plan steht, dem der Konsultationstakt folgt.",
    why: "Ein Review dauert Minuten, und worauf man wartet, ist kein Verdikt, sondern die Reviewer, die es erzeugen. Eine abgeschlossene Runde ist eine andere Frage — „was war“ — und das ist ein Protokoll, das eine Tabelle mit Filtern, Sortierung und Suche braucht, keine Seitenleiste. Die Seitenleiste behält also nur die Gegenwart.",
    setup: "Nichts einzustellen. Der Server schreibt eine Runde beim Start auf die Platte und aktualisiert sie, während die Reviewer vorankommen — das Bild überlebt ein neu geladenes Fenster, einen Neustart der Erweiterung und einen abgeschossenen Server.",
    usage: "Es gibt nichts anzuklicken: eine laufende Runde ist bereits offen, und wenn sie fertig ist, verlässt sie die Seitenleiste. Alles, was je gelaufen ist — fertig, unterbrochen, jeder Reviewer, jede Zahl — steht unter **Show review rounds**: das Listensymbol in der Titelleiste der ConnectOtherAIs-Seitenleiste oder die Befehlspalette, und solange eine Frage auf Sie wartet, öffnet es auch der Eintrag in der Statusleiste.\n\n**In Consultation cadence eine Zeile je Plan, dem der Takt folgt** — `PLAN_x.md · epics closed 4/14 · consultation for epics 4-6: due` — und der Branch, auf dem er liegt. Sie sagt, welche Gruppe von Epics ihre Konsultation schuldet und ob sie *taken* ist, wie viele der riskanten Stücke beraten wurden, und bei *Require*, dass die Code-Runde darauf wartet. Sie wird als Warnung gezeichnet, solange eine Konsultation fällig ist oder die Takt-Aufzeichnung nicht gelesen werden kann, und als schlichte Zeile, sobald nichts zu tun ist.\n\n**In Active consultations eine Karte je gerade laufender Konsultation**: wer wen fragt und mit welchem Modell, welche Art sie ist und wofür, der Branch, *asking* oder *open* mit dem aktuellen Zug von wie vielen, wie lange seit dem letzten Geschehen und die Token bisher. Eine Konsultation, deren Prozess zwischen Fragen und Hören starb, liest sich *resumable* — der Zug wurde nicht gezählt, und die KI nimmt sie mit ihrer Konsultationskennung wieder auf. Der Dateisystem-Alarm steht auf der Karte, wenn er ausgelöst wurde. Läuft nichts, sagt der Abschnitt das, und wo die beendeten stehen.\n\nDieses Protokoll enthält Ihre GESPRÄCHE ebenso wie Ihre Runden, jedes in einem eigenen Tab — **Rounds** und **Conversations** —, denn „was hat mich heute gekostet“ ist selten eine Frage nach nur einem davon. Ein Gespräch hat kein Repository, keinen Branch, keine Stufe und kein Urteil, also blendet sein Tab diese Spalten und ihre Filter aus, statt sie leer zu zeigen: ein Chat hängt an keinem Branch. *Das Protokoll: Show review rounds* geht die Seite Tab für Tab durch.\n\nDie Spalte **Took** im Protokoll nennt zwei Zeitspannen, nicht eine: `2m 10s · 5m 0s` ist, wie lange die Reviewer liefen, und dann, wie lange das ENTSCHEIDEN dauerte — vom Ende der Runde bis zu ihrer letzten Entscheidung. Eine Runde, über die niemand entschieden hat, zeigt eine Zahl, ein Gespräch ebenso. Ein `resolve`-Aufruf stempelt alles, was er berührt, mit einem einzigen Zeitpunkt; bei einer gewöhnlichen Runde ist die zweite Zahl also das Entscheiden, bei einer Runde, zu der Sie nach dem Mittagessen zurückkamen, zählt das Mittagessen mit.\n\n**Jede Zeile endet mit Export, und das ganze Protokoll kann als Datei herausgehen.** Der **Export** einer Runde schreibt eine CSV-Datei dorthin, wo Sie wollen: wann sie lief, auf welchem Branch und in welchem Repository, ihr Urteil, an wie vielen Befunden sie hing, beide Zeiten, die Token, die drei Kostenzahlen und eine Zeile je Reviewer — und danach eine Zeile je BEFUND, die die Spalten der Runde noch einmal trägt, dazu Ihre Entscheidung darüber, in denselben Worten wie auf der Seite (*took*, *declined*, *open*), mit dem Grund einer Ablehnung daneben.\n\nFür mehr als eine Runde haken Sie sie an. Das Kästchen in der Kopfzeile wählt jede Runde, auf die die Filter gerade passen — über alle Seiten hinweg, nicht nur die Seite auf dem Bildschirm —, und die Schaltfläche sagt, wie viele Sie gewählt haben und wie viele davon außer Sicht sind (*Export 41 selected (3 hidden)…*). Filtern macht eine Auswahl nie rückgängig; **Clear selection** verwirft sie in einer Geste. Ein Massenexport meldet, wie viele Runden er gelesen hat, und lässt sich abbrechen — halten Sie ihn an, wird nichts geschrieben —, und über fünfhundert Runden fragt er vorher nach.\n\n**Eine Runde kann übersprungen werden.** Das Feature-Review hält eine Runde, die niemand ausführen konnte — kein Anbieter für Features angehakt, das Gate ausgeschaltet, ein Plan mit weniger als drei Epics —, als **skipped — did not block** fest: ein neutrales Abzeichen, keine Dauer, und aufgeklappt der Grund des Servers (mit ×N, wenn sich dasselbe Überspringen wiederholt hat). Sie hat das Release nicht aufgehalten; sie steht da, damit das Fehlen eines Reviews festgehalten ist statt unsichtbar.",
    whatCanGoWrong: "Eine Runde, die ein abgestürzter Server zurückließ, wird beim nächsten Start auf *interrupted* gesetzt und verschwindet hier; im Protokoll bleibt sie. Steht in Active gates *Nothing is running*, während Ihr Assistent sagt, er reviewe gerade, schreibt der Server, mit dem er spricht, woanders hin — ein `COAI_DATA_DIR` in seiner Konfiguration, das dieses Fenster nicht teilt.\n\nIn einer exportierten Datei bleibt eine fehlende Messung fehlend: eine Runde, deren Token niemand festgehalten hat, lässt die Zelle leer statt null — denn null ist eine Zahl, die jemand gemessen hat. Eine Runde, deren Befunde nicht GELESEN werden konnten, wird nie als Runde geschrieben, die nichts gefunden hat: die Spalte `findings_read` sagt für jede — *loaded*, *not recorded* oder *failed* —, die Befundspalten bleiben in den letzten beiden Fällen leer, und die Meldung nach dem Export nennt jede Runde, die nicht gelesen werden konnte. Konnte gar nichts gelesen werden, wird keine Datei geschrieben und der Speicherdialog öffnet sich nicht.\n\nNichts in der Datei kann beim Öffnen ausgeführt werden: ein Branch oder ein Titel, der mit `=`, `+`, `-` oder `@` beginnt, wird als Text geschrieben — auch dann, wenn er sich hinter einem Leerzeichen versteckt. Der Zeitpunkt wird zweimal geschrieben — wie gespeichert, in UTC, und nach der Uhr Ihrer Maschine mit angegebenem Versatz —, denn eine Datei kann nicht wissen, in welcher Zeitzone sie in einem Jahr gelesen wird. Den Speicherdialog abzubrechen tut nichts und sagt nichts; ein fehlgeschlagener Schreibvorgang sagt, was fehlschlug, und behauptet nie einen Erfolg. Gegen ein `coai-mcp`, das älter ist als dieses Release, funktioniert ein Massenexport weiterhin — eine Runde nach der anderen, vier auf einmal.",
  },
  "the-rounds-log": {
    title: "Das Protokoll: Show review rounds",
    whatItIs: "**Show review rounds** ist die Seite, die alles enthält, was bereits geschehen ist. Sie öffnet sich über das Listensymbol in der Titelleiste der ConnectOtherAIs-Seitenleiste, über die Befehlspalette und — solange eine Frage auf Sie wartet — über den Eintrag in der Statusleiste. Jede Frage, die auf Sie wartet, steht ganz oben, unter *Open questions — a review is waiting on you*, jede mit **Answer…**. Darunter sechs Tabs: **Rounds**, **Conversations**, **Consultations**, **Questions** — jede Frage an den Question consultant, mit ihren Modellen zum Aufklappen —, **What each AI has used** und **What it keeps missing**.",
    why: "Die Seitenleiste zeigt absichtlich nur die Gegenwart: worauf jemand wartet, sind die Reviewer, die gerade laufen. „Was ist passiert“ ist eine andere Frage — ein Protokoll, das Filter, Sortierung, Suche und mehr als eine Seite braucht —, und es sind fünf Fragen statt einer: was das Gate entschieden hat, was die Chats gekostet haben, ob das Beraten geholfen hat, was alles zusammen gekostet hat, und was die KI immer wieder nicht von selbst sieht.",
    setup: "Nichts einzurichten. Die Seite liest, was der Server aufgezeichnet hat, und schreitet während einer laufenden Runde von selbst voran, ohne Ihre Sortierung, Ihre Filter oder Ihre Suche zu verlieren.",
    usage: "**Rounds** öffnet auf heute. Die Werkzeugleiste hat ein Suchfeld — Betreff, Branch, Repository, Reviewer, Modelle —, **From** und **To**, die neben dem Tag auch eine Uhrzeit annehmen, **Today**, **All dates**, um den Zeitraum wegzunehmen, je einen Filter für Repository, Branch, Stufe, Status, Urteil und Anbieter, und **Clear**, das Suche, Daten und jeden Filter zugleich wegnimmt. **Export selected…** und **Clear selection** sind für die Zeilen, die Sie anhaken. Zweihundert Zeilen werden auf einmal gezeigt, und **◀ Newer** und **Older ▶** blättern eine Seite weiter. Ein Klick auf eine Spalte sortiert, ein Klick auf eine Zeile zeigt ihre Reviewer.\n\n**Conversations** ist dieselbe Tabelle für Ihre Chats: ihre Spalte **Round** heißt **Turn** und ihre Spalte **Reviewers** heißt **Who answered**, und wofür ein Gespräch keine Antwort hat — Repository, Branch, Stufe, Urteil, Befunde, die Kästchen und der Export —, wird ausgeblendet statt leer gezeigt. **Today**, **Week**, **Month**, **Year** und **All** wählen den Zeitraum.\n\n**Consultations** hat dieselben Zeitraum-Schaltflächen und eine Zeile je Konsultation: wann sie begann, ihre Art und wofür sie war, wer wen gefragt hat, wo, wie viele Züge, wie sie endete und mit welchem Ergebnis, was sie gekostet hat, was gefragt und was geraten wurde. Eine Zeile, über die noch niemand entschieden hat — kein Ergebnis, oder eines, das abgelaufen ist —, hat **record…**, das nach *Solved*, *Not solved* oder *Abandoned* fragt und dann nach einem optionalen Satz für das Protokoll; Escape in einem der beiden Schritte lässt sie offen. Eine gescheiterte Konsultation hat keines, denn sie hat keinen Rat hervorgebracht, über den man urteilen könnte. Gezeigt werden die neuesten zweihundert, und die Seite sagt es, wenn es mehr gibt.\n\n**What each AI has used** sind die Ausgaben und hat einen eigenen Artikel. **What it keeps missing** zählt über den gewählten Zeitraum die Befunde, die die KI angenommen hat — nach Kategorie, nach Reviewer-Rolle und nach Anbieter, in den Spalten *taken*, *of* und *%* —, denn ein angenommener Befund ist etwas, das sie nicht gesehen und dann als wertvoll anerkannt hat. Unter den Zählungen listet *Rejected, and raised again anyway* die Meinungsverschiedenheiten, die sie noch verteidigt: mit Begründung abgelehnt und von einem anderen Reviewer erneut erhoben.",
    whatCanGoWrong: "**Ein Tab sagt, dass er liest, bis er etwas hat**, und sagt dann, was schiefging, wenn nichts ankommt, statt leer zu bleiben — ein leerer Tab sieht auch genau so aus wie eine Übertragung, die nie angekommen ist.\n\n**What it keeps missing wird vom Server gezählt.** Ein `coai-mcp` älter als 0.37.0 kann es nicht nach Zeitraum aufteilen; der Tab sagt das und zeigt die gesamte Zeit, statt die gesamte Zeit als heute auszugeben. *Nothing decided in this period* und *Nothing decided yet* sind verschiedene Sätze: der erste heißt, dass ein weiterer Zeitraum, oder All, etwas zeigen würde.\n\nEin in From oder To getipptes Datum ist Ihr eigener Zeitraum, deshalb ist auf Conversations keine Zeitraum-Schaltfläche markiert, solange es gilt.",
  },
  "what-each-ai-has-used": {
    title: "Was jede KI verbraucht hat: Token, Geld und Zeit",
    whatItIs: "Der Tab **What each AI has used** von **Show review rounds**. Ein Balken pro Anbieter über einen Tag, eine Woche, einen Monat oder ein Jahr — **Today**, **Week**, **Month** und **Year** über den Balken wählen, welcher, standardmäßig Today: Token hinein und hinaus, **Geld**, wie viele Läufe, wie viele gescheitert, Gesamt- und Durchschnittszeit — und eine Zeile unten, die alle Anbieter zusammenzählt. Chat-Züge werden ebenfalls gezählt, und sie haben einen eigenen Abschnitt auf diesem Tab: oben **Reviewers**, eine Linie, darunter **Chat** — eine Karte pro Anbieter UND Modell, in der Form der **Reviewers**-Karten darüber, denn ein Gespräch wechselt das Modell, und ein Preis gehört zum Modell. Eine Chat-Karte führt beide Preise, was sie im gewählten Zeitraum gekostet hat, was sie **insgesamt** gekostet hat — unabhängig vom oben gewählten Zeitraum — und zwei Zähler: **Asked**, wie oft *take the question* und *add the question* benutzt wurden, und **Opened**, wie oft ein Chat überhaupt durch eine seiner sechs Türen geöffnet wurde. Jeder Abschnitt zählt sich selbst zusammen, denn die beiden Protokolle schreiben verschiedene Programme und dürfen nicht nach Augenmaß addiert werden. Unter beiden Abschnitten zählt eine zweite Linie und eine weitere Zeile die beiden Protokolle zusammen, denn „was hat mich das gekostet“ ist eine Frage, gleich welche Hälfte des Produkts es ausgegeben hat. Chat-Züge erscheinen außerdem, Zug für Zug, im Tab **Conversations** derselben Seite.",
    why: "Eine Prüfrunde gibt in jeder Runde echtes Geld aus, und die Frage „was hat mich das diesen Monat gekostet“ lässt sich aus einer Sitzungsdatei nicht beantworten: Sitzungen werden im Lauf der Runden überschrieben und halten je einen Branch.",
    setup: "Für die Token gibt es nichts einzurichten: der Server hängt pro Prüfer eine Zeile an `usage.jsonl` in seinem Datenverzeichnis, und dieser Tab liest sie.\n\nFür GELD gibt es eine Sache, und nur Sie können sie liefern: **was dieser Anbieter pro Million Token verlangt, hinein und hinaus**, unter **Price** auf der Karte dieses Modells auf **Models**, in den Settings (**$ / 1M in**, **$ / 1M out**). Dieses Produkt liefert absichtlich keine Preistabelle mit — eine mitgelieferte ist falsch für jeden mit Pauschalabo, falsch beim ersten Preiswechsel eines Anbieters, und in beiden Fällen still falsch. Tragen Sie einen Satz ein, erscheint das Geld dieses Anbieters; lassen Sie ihn leer, bleibt ein Strich.",
    usage: "**Ein gescheiterter Prüfer wird mitgezählt.** Ein Lauf, der neunzig Sekunden verbrannt und nichts geantwortet hat, ist genau das, was eine Ausgabenaufzeichnung nicht verstecken darf, also trägt jede Zeile ihr Ergebnis und die Zahl der Fehlschläge steht neben den Token.\n\n**Die Tilde trägt Bedeutung.** `$0.42` ist, was ein Anbieter berechnet hat; `~$0.42` ist, was Ihr eigener Satz ergibt. Claude meldet seine Kosten, Codex und Antigravity melden nur Token — bei diesen beiden also eine Tilde oder ein Strich, nie eine nackte Zahl. Die Summe hält die Hälften aus demselben Grund getrennt: sie liest sich als `$0.18 + ~$0.31`, statt eine Tatsache zu einer Rechnung zu addieren und das Ergebnis als eines von beiden auszugeben.\n\nUnter einem Dollar wird Geld mit vier Dezimalstellen gezeigt. Eine Runde, die acht Hundertstel Cent gekostet hat, ist eine echte Zahl, und sie auf `$0.00` zu runden sagt, dass die Ansicht nicht zählt.\n\n**Das ✕ auf einer Karte entfernt sie aus diesem Diagramm**, nach einer Rückfrage — eine Anbieterkarte unter *Reviewers*, ein Paar aus Anbieter und Modell unter *Chat*. Aus dem Protokoll auf der Platte wird nichts gelöscht: die Karte hört auf, das bereits Aufgezeichnete zu zählen, und kommt zurück, sobald dieser Anbieter das nächste Mal läuft oder dieses Modell antwortet. Die Chat-Zeile *nothing chosen* hat kein ✕, denn es gibt kein Paar zu vergessen.\n\n**Ein Team server, bei dem Sie angemeldet sind, fügt einen eigenen Block hinzu**, unter seinem Namen: die Token, Läufe und Fehlschläge seiner Anbieter, wie der SERVER sie gezählt hat — er führt das Protokoll, also rechnet hier nichts nach —, und, wenn er beides bedient hat, wie viel auf Reviews und wie viel auf Gespräche entfiel. Ein Administrator dieses Servers bekommt zusätzlich **Show the whole company**, das den Block von Ihrer eigenen Nutzung auf die aller erweitert und zurück; für alle anderen würde der Server das ablehnen, deshalb wird die Schaltfläche gar nicht gezeichnet.",
    whatCanGoWrong: "Token werden pro Anbieter gezählt, weil eine einzige Regel für mindestens einen falsch wäre: Codex faltet gecachte Token IN die Eingabezahl, Claude meldet sie DANEBEN, und bei Antigravity liegen Denk-Token innerhalb der Ausgabe. Claude meldet denselben Lauf zudem zweimal mit verschiedenen Zahlen; der aggregierte wird genommen.",
  },
  "questions-waiting": {
    title: "Eine Frage, die auf Sie wartet",
    whatItIs: "Braucht das Gate einen Menschen, erscheint oben in der Seitenleiste unter **Active questions** eine Karte mit der Frage und den weiterhin blockierenden Befunden — die eine Karte, die eine Frage hat, mit den Antworten der Berater darunter, falls es welche gab. Ein Dialog öffnet sich, in der Statusleiste erscheint ein Eintrag, und das Symbol in der Titelzeile wird grün. Nur die Fragen des GATES kommen hierher: ein Verdikt `call_human` oder eine Frage, die eine KI stellt, während das Gate hält oder im Fenster für die zweite Runde eines Feature-Reviews. Die eigenen Fragen einer KI zu ihrer Arbeit werden in ihrem Chat gestellt, nie hier.",
    why: "Hinter dieser Frage steht eine BLOCKIERTE Runde. Eine Benachrichtigung, die man verpassen kann, taugt dafür nicht — daher drei Oberflächen, und das Schließen des Dialogs verliert nichts.",
    setup: "Für den gewöhnlichen Fall nichts einzustellen: der Server schreibt die Frage als Datei in das Verzeichnis, das die Erweiterung ohnehin beobachtet, und keine der beiden Hälften öffnet einen Port. Ein Fall braucht doch eine Einstellung. Eine Runde, die in einer ANDEREN Installation läuft — etwa eine Claude-Code-Sitzung in WSL —, schreibt ihre Frage in das Datenverzeichnis JENER Installation, und ein Fenster, das nur sein eigenes beobachtet, zeigt sie nie, während die Runde blockiert. `coai.alsoWatchDataDirectories` benennt die anderen Verzeichnisse: Fragen aus einer anderen Installation erscheinen neben den eigenen, und die Antwort wird neben die Frage geschrieben — dorthin, wo der fragende Server hinsieht. Der Tab **Setup › MCP server** der Settings listet sie unter *Questions from another installation are also answered here*, und ein Verzeichnis, das nicht gelesen werden kann, wird dort mit dem Grund genannt — Schweigen sähe genau so aus wie eine Installation, die nichts gefragt hat. Geteilt werden nur die Fragen; keine Datenbank wird über die Grenze hinweg geöffnet. Aus einem Windows-Fenster muss ein WSL-Verzeichnis so benannt werden, wie Windows es erreicht: `\\\\wsl.localhost\\<distro>\\home\\<user>\\.local\\share\\coai-mcp` — ein im WSL-Stil geschriebener Pfad (`/home/…`) wird von Windows aus nie beobachtet; da beide Fenster diese Einstellung teilen, wird er als Verzeichnis der anderen Seite aufgeführt und hier übersprungen, nicht abgelehnt, und ein Windows-Pfad wird in WSL ebenso übersprungen.",
    usage: "Antworten können Sie im Panel, im Dialog, aus der Statusleiste oder mit **Answer the open question…** — dem Symbol in der Titelleiste der ConnectOtherAIs-Seitenleiste, das fragt, welche, wenn mehr als eine wartet, und sagt, wenn keine wartet. Der Eintrag in der Statusleiste öffnet **Show review rounds**, dessen Block **Open questions** an jeder Frage eine Schaltfläche **Answer…** hat. Es ist alles dieselbe Handlung. Ein Hinweis `call_human` bietet nur die drei Entscheidungen an; eine Frage, die eine KI gestellt hat, bietet zuerst ein Feld für Ihre eigenen Worte und danach die Entscheidungen — Ihre Worte gehen an die KI zurück und entscheiden nichts für das Review — das tut nur eine Entscheidung. Ihre Antwort geht genau so an die fragende KI zurück, wie Sie sie gegeben haben — nichts übersetzt sie, in keiner Richtung.",
    whatCanGoWrong: "Auch das Verdikt `call_human` erzeugt so eine Karte, damit ein Gate mit aufgebrauchten Runden Sie erreicht, selbst wenn die KI schweigt. Das war nicht immer so: früher war das Verdikt nur eine Anweisung an die KI, und ein Mensch konnte den ganzen Tag auf das Panel sehen, ohne zu erfahren, dass er gerufen wurde.",
  },
  "prompts-in-full": {
    title: "Die Prompts, vollständig",
    whatItIs: "Der vollständige Text jedes Prompts, den dieses Produkt an einen Prüfer sendet — die vier universellen, die zwanzig engen Linsen, der Konventionsdurchgang, die drei Dokument-Prompts, die Dokument-Zusammenfassung und das Feature-Review. Hier ist nichts umschrieben; das liest das Modell.",
    why: "Eine Prüfung, die man nicht nachprüfen kann, muss man glauben. Genau zu wissen, was gefragt wurde, erlaubt zu beurteilen, ob eine Antwort fair war — und ob ein Befund, dem Sie widersprechen, von einem schlechten Modell oder einer schlechten Frage kam.",
    setup: "Nichts einzurichten. Was unten steht, wird von einem Test gegen die eigenen Prompt-Dateien des Servers geprüft, kann also nicht von dem abweichen, was wirklich läuft.\n\nDer Prompt **conventions** steht für sich, weil er der einzige Prompt einer eigenen Code-Rolle ist, Conventions: keine Linse auf die Frage einer anderen Rolle, sondern eine andere Frage, gestellt in jeder Runde, die diese Rolle hat. Die Regeln kommen mit ihm — die eigenen `CLAUDE.md`, `AGENTS.md`, `GEMINI.md` und `.claude/rules` des Projekts, gelesen aus dem Worktree des geprüften Commits und wörtlich zitiert, bis 40 KB, wobei alles Ausgelassene benannt und nicht still verworfen wird.",
    usage: "Jeder Prompt endet mit derselben Disziplin: ein Befund muss eine konkrete Situation und das falsche Ergebnis nennen, das sie erzeugt; vier Arten von Nicht-Befunden sind benannt und verboten; und es steht ausdrücklich da, dass eine leere Befundliste eine gültige Antwort ist — ein Prüfer, dem man sagt, immer etwas zu finden, wird immer etwas finden.\n\nJeden davon können Sie überschreiben: legen Sie eine Datei mit dem Namen des Prompts in `prompts/` im Datenverzeichnis des Servers ab, und sie gewinnt, solange sie existiert. Löschen Sie sie, gilt wieder der ausgelieferte Text.",
    whatCanGoWrong: "Eine Überschreibung wird nicht geprüft. Ein Prompt, der das Befundschema nicht verlangt, erzeugt Antworten, die nicht geparst werden können, und die Runde meldet diesen Prüfer als nicht parsbar — mit seiner Rohantwort auf der Platte, damit Sie sehen, wonach Sie gefragt haben.",
  },
  "the-help-page": {
    title: "Diese Seite: Suche, Sprache und Textgröße",
    whatItIs: "Das gelbe ? in der Titelzeile des Panels öffnet diese Hilfe. Die Liste zeigt jeden Artikel mit seiner ersten Zeile; das Feld oben durchsucht alle; die Auswahl wechselt die Sprache; die ±-Schaltflächen ändern die Textgröße, und das Paar daneben den Textton — heller, oder matter und wärmer. Jede ConnectOtherAIs-Seite trägt dieselben zwei Paare neben ihrem Titel, und ein Druck auf eines davon ändert jede geöffnete Seite.",
    why: "Ein Settings-Tab mit Dutzenden Bedienelementen braucht einen Ort, der ausführlich sagt, was jedes tut: das kleine ? neben einem Element fasst einen Satz, diese Seiten fassen die Gründe dahinter. Die Textgröße steht hier, weil Sehkraft nichts ist, worüber man streitet: fünf Schritte in jede Richtung sind etwa ×1,6 hinauf oder hinunter.",
    setup: "Nichts einzustellen. Der Sprachschalter schreibt `coai.helpLanguage` und gilt nur für diese Seiten — es ist nicht die Sprache, in der eine andere KI in einem Chat antwortet; das ist **Answer in**, auf dem Tab **Chat** der Settings. Die ±-Schaltflächen schreiben `coai.uiScale` und `coai.textTone`; die Null des Tons ist die Farbe Ihres eigenen Themes, ein unberührter Regler ändert also nichts. Beides sind echte Einstellungen und werden auf Ihre anderen Maschinen synchronisiert.",
    usage: "Gesucht wird in den Überschriften UND im vollen Text jedes Artikels in der gezeigten Sprache — ein Wort, das Ihnen aus einem Absatz in Erinnerung blieb, findet also den Artikel, in dem es stand. Escape schließt einen Artikel zurück zur Liste, und Back behält das Getippte.\n\nEin nicht übersetzter Artikel zeigt Englisch mit sichtbarem Hinweis, keine leere Seite.",
    whatCanGoWrong: "Dass eine Übersetzung dem Englischen hinterherhinkt, ist normal und wird gekennzeichnet. Was nicht passieren kann, ist ein fehlender Artikel: ein Abdeckungstest lässt den Build scheitern, wenn zu einem Befehl oder einer Einstellung nichts geschrieben steht. Genau deshalb kann diese Seite nicht still zur Beschreibung eines Produkts werden, das es nicht mehr gibt.",
  },
  "the-protocol": {
    title: "Unter der Haube: das Protokoll, dem Ihre KI folgt",
    whatItIs: "Zwölf Werkzeuge in fester Reihenfolge. `open` öffnet eine Sitzung für Repository und Branch. `review_plan` schickt den Plan an alle Reviewer. `resolve` hält für JEDEN Befund fest, ob er angenommen oder abgelehnt wurde. `review_code` tut dasselbe für das Diff, mit vier Rollen je Hersteller. `review_document` ist das andere Tor — ein DOKUMENT statt eines Diffs, ohne Planrunde davor und mit einer eigenen Sitzung je Dokument. `review_feature` ist das vierte Tor, einmal aufgerufen am Ende eines Plans mit drei oder mehr Epics, vor dem Release: jede frühere Runde sah einen Ausschnitt, und diese schickt das ganze Feature an die Reviewer, die Sie für Features angehakt haben — ein Plan mit weniger Epics wird als *skipped* festgehalten und blockiert nicht. `providers` zeigt den Zustand, `status` bringt ein wieder aufgenommenes Gespräch zurück in den Kontext, `ask_human` bringt die eigenen Fragen des Tors zu Ihnen und schickt die eigenen Fragen des Assistenten in seinen Chat zurück. Und davor `ask_consultants`: der Fragen-Konsultant, bei dem jede von Ihnen eingerichtete Modellzeile die Frage des Assistenten gleichzeitig beantwortet, sodass Sie nur gefragt werden, was sie nicht klären konnten (nach den ersten zwei Fragerunden zum angenommenen Plan, bis zum Release; bei einem Produktionsrisiko werden sie zuerst gefragt, und ihre Antworten kommen mit der Frage). `consult` und `close_consult` sind die beiden, die nichts abriegeln: mit `consult` fragt ein festgefahrener Assistent das Modell eines anderen Herstellers zu Ihrem Arbeitsbaum, wie er gerade ist, und bekommt eine Antwort statt eines Urteils; mit `close_consult` hält er fest, wie diese Konsultation ausging — *solved*, *not solved* oder *abandoned* —, sobald er den Rat überprüft hat.",
    why: "Die Reihenfolge hält durch Verweigerung, nicht durch gutes Benehmen: `review_code` verweigert, solange keine Planrunde *proceed* erreicht hat — eine Stufe zu überspringen ist also unmöglich und nicht bloß „nicht empfohlen“.",
    setup: "Nichts einzustellen — das steuert Ihre KI. Die Reihenfolge sagt ihr genau der Absatz, den Sie ins Repository eingefügt haben.",
    usage: "Eine Ablehnung verlangt eine Begründung, und die Begründung bleibt erhalten: ein abgelehnter Befund zählt in weiteren Runden nicht, bis ein Reviewer ihn mit einem neuen Argument erneut vorbringt. Genau das hindert die Schleife daran, eine Entscheidung neu aufzurollen, die Sie schon getroffen haben.",
    whatCanGoWrong: "Eine Runde, in der NIEMAND geantwortet hat, geht nie durch. Ein leeres Ergebnis ist das Fehlen von Belegen, nicht der Beleg für ein Fehlen: das Gate ruft stattdessen einen Menschen. Das ist der einzige Fall, in dem „keine Befunde“ nicht „freigegeben“ heißen darf.",
  },
  "where-reviewers-run": {
    title: "Unter der Haube: wo ein Reviewer wirklich läuft",
    whatItIs: "Jeder Reviewer läuft standardmäßig in einem leeren Verzeichnis, auf der Plan-Stufe wie auf der Code-Stufe. Der Schalter der Code-Stufe — was ein Reviewer bekommt — hat zwei Stellungen: Fast gibt ihm den zusammengesetzten Prompt und nichts zu erkunden; Full gibt ihm zusätzlich EIN git-worktree, festgenagelt auf den Commit des Branches, nur lesbar.",
    why: "Fast ist die Voreinstellung, weil es gemessen und nicht bevorzugt wurde. Auf einem Commit ließ das Wegnehmen des Checkouts jedes gehostete Modell MEHR nützliche Fehler finden — von vier auf acht, von sechs auf zehn, von sechs auf sieben —, bei der Hälfte bis einem Drittel der Eingabe-Token, ohne einen einzigen falschen Befund, und drei echte Fehler kamen zum Vorschein, die kein Lauf MIT Checkout erreicht hatte. Ein Reviewer, dem man ein Repository gibt, verwendet seine Aufmerksamkeit darauf, zu entscheiden, wo er hinsieht; ein Reviewer, dem man ein Diff gibt, liest das Diff. Auf der Plan-Stufe war die Wirkung noch krasser: acht Minuten und immer noch am Laufen, bei einem Dokument von fünfzehn Kilobyte.",
    setup: "Nichts einzustellen. Die Worktrees liegen im Datenverzeichnis des Servers und werden beim Öffnen einer Sitzung aufgeräumt, sodass eine abgebrochene Runde nichts hinterlässt. Full kostet ein Checkout pro Runde; Fast keines.",
    usage: "Was der Prompt enthält, ändert sich zwischen beiden nicht: das Diff und die aufgeschriebenen Regeln dieses Projekts stellt der Server in jedem Fall zusammen, der einzige Unterschied ist also, ob es ein Repository gibt, in das man abschweifen kann. Wählen Sie Full, wenn die Bedeutung einer Änderung von Aufrufern abhängt, die das Diff nicht zeigt — und wissen Sie, dass es auf dem gemessenen Commit weniger fand. Die Plan-Stufe hat keinen Schalter, und ihr Preis, im Klartext: ein Plan-Reviewer kann nicht prüfen, ob ein Verweis der Form `file.cs:line` im Plan echt ist.",
    whatCanGoWrong: "Der eine Wiederholungsversuch, den ein Reviewer bekommt, läuft aus demselben Grund ebenfalls in einem leeren Verzeichnis: die Reparatur bittet um die Antwort im Schema, nicht um weitere Erkundung. Ihm das Checkout erneut auszuhändigen war das, was eine von drei Code-Runden einen Reviewer kostete.",
  },
  "when-a-reviewer-fails": {
    title: "Unter der Haube: was passiert, wenn ein Reviewer scheitert",
    whatItIs: "Sechs benannte Ausgänge und niemals eine stille Null: geantwortet, ins Timeout gelaufen, mit Fehlercode beendet, ins Ratenlimit gelaufen, nicht startbar, oder mit etwas geantwortet, das sich nicht parsen lässt. Eine Runde, die mit vier von sechs Reviewern durchlief, sagt genau das — mit Namen.",
    why: "Ein Panel, das nicht reviewt hat, ist kein Panel, das zugestimmt hat. Jede unvollständige Runde meldet sich als unvollständig, und der Reviewer-Satz im Panel nennt, wer scheiterte und warum.",
    setup: "Nichts einzustellen. Ein Reviewer im Ratenlimit wird nach einer Pause genau einmal wiederholt — es sei denn, der Hersteller hat gesagt, das Limit gelte für den TAG, und das heilt keine Wiederholung.",
    usage: "Eine Absage trägt die eigenen Worte der CLI, nach Inhalt gewählt und nicht nach Position: die erste Zeile, die einen Fehler ankündigt, vorbei an Stack-Frames und Versionsbannern. Für fünf bekannte Absagen — geschlossene CLI, nicht vertrautes Verzeichnis, fehlende Binärdatei für die Plattform — wird gesagt, WAS ZU TUN IST, statt was gedruckt wurde.",
    whatCanGoWrong: "Eine Antwort, die sich nicht parsen ließ, wird unter `unparseable/` im Datenverzeichnis gespeichert, und die Absage nennt die Datei. Das kam daher, dass dieselbe Antwort, von Hand nachgestellt, sauber durchlief — die Meldung nannte also ein Symptom, das sich nicht untersuchen ließ.",
  },
  "settings-and-the-server": {
    title: "Unter der Haube: wie eine Einstellung den Server erreicht",
    whatItIs: "Was Sie im Settings-Tab einstellen, wird in eine Datei im Datenverzeichnis des Servers geschrieben, und der Server liest diese Datei neu, sobald sie sich ändert.",
    why: "Früher erreichten Einstellungen den Server nur im eingefügten Konfigurationsblock, und jede Änderung einer Schwelle wurde zur Prozedur: Block kopieren, Client-Konfiguration finden, einfügen, neu starten. Und sie galten nur beim Start — ein Bruch, der von beiden Seiten unsichtbar war, weil das Panel sofort speichert und das auch so sagt.",
    setup: "Nichts einzustellen. Eine Änderung im Settings-Tab gilt ab der NÄCHSTEN Runde: kein Neustart, kein erneutes Einfügen.",
    usage: "Eine Variable in der Konfiguration des Assistenten schlägt die Datei weiterhin: sie ist spezifischer als eine Datei, die jedes Fenster überschreiben kann.\n\nGeschrieben wird nur, was von den Voreinstellungen ABWEICHT — eine Einstellung auf ihre Voreinstellung zurückzusetzen entfernt sie also aus der Datei, statt sie festzuschreiben.\n\nGetrennte Einstellungen je Seite: auf einem Rechner können mehrere Arbeitsumgebungen liegen - ein lokales Fenster und eine oder mehrere WSL-Distributionen - und VS Code gibt ihnen DIESELBE Einstellungsdatei. Schalten Sie **Separate settings for each side** ein, in Settings → This side, und jede Seite behält ihre eigenen Werte, angelegt aus dem, was sie in diesem Moment hatte, sodass sich bis zur ersten Änderung nichts ändert. Für eine Person, die auf einem Rechner für zwei Firmen arbeitet, heißt das: ein anderer Proxy, ein anderer CLI-Pfad und ein anderer Tresorschlüssel je Seite. Textgröße und Hilfesprache bleiben gemeinsam - sie gehören Ihnen und nicht der Arbeit.",
    whatCanGoWrong: "Eine halb geschriebene Datei lässt die letzte funktionierende Konfiguration stehen. Ein zerrissener Lesevorgang mit leerer Herstellerliste hätte jeden Reviewer scheitern lassen und wäre von einem Panel gemeldet worden, das mit sich selbst einig ist.",
  },
  "move-your-config": {
    title: "Die Einrichtung mitnehmen: Export config und Import config",
    whatItIs: "Das ⋯-Menü der ConnectOtherAIs-Seitenleiste → **Export config** schreibt alles, was Sie geändert haben, in eine JSON-Datei: jede Einstellung, deren Wert vom Standard abweicht, und den Text jedes Prompts, den Sie geschrieben haben. **Import config** liest eine solche Datei zurück und wendet sie nach einer Bestätigung an.",
    why: "Ein über Wochen abgestimmtes Panel — Prüfer, Modelle, Schwellen, Rollen und ihre Prompts — wird sonst auf jedem neuen Rechner von Hand neu gebaut und per Screenshot mit Kollegen geteilt.",
    setup: "Nichts einzurichten. Die Datei ist lesbares JSON, das Sie in einem Repository ablegen oder weitergeben können.",
    usage: "Der Import sagt vorher, was er tun wird: wie viele Einstellungen und Prompt-Texte, wie viele dieser Texte vorhandenen Text ersetzen, und alles, was er NICHT anwendet, jeweils mit Grund. Einstellungen, die die Datei nicht nennt, bleiben, wie sie sind, und nichts wird gelöscht. Ein CLI-Pfad, den dieser Rechner für einen Prüfer schon hat, bleibt erhalten, weil der Export jeden Pfad weglässt.",
    whatCanGoWrong: "**Ein Geheimnis und der Aufbau dieses Rechners reisen nie mit**: der Zugangsschlüssel zum Tresor, das Datenverzeichnis, welche Seite des Rechners dieses Fenster ist, die Ordner, die eine Festplatten-Zeile des Fragen-Konsultanten lesen darf, und jeder CLI-Pfad. Token sind gar keine Einstellungen und werden nie gelesen. Überschreibungen pro Seite werden weder exportiert noch geändert — nur der gemeinsame Wert.\n\nEine Datei einer anderen Version dieser Erweiterung wird mit einem Satz abgelehnt statt halb gelesen, und eine Einstellung, die dieser Build nicht kennt, wird namentlich abgelehnt, während der Rest angewendet wird. Scheitert ein Schreibvorgang mittendrin, wird alles, was der Import schon geändert hatte, zurückgesetzt, und die Meldung sagt es — oder nennt, was nicht zurückging.",
  },
  "models-move-into-the-catalog": {
    title: "Ihre Modelle ziehen in einen Katalog um: Models",
    whatItIs: "Diese Version verschiebt jedes Modell, das Sie definiert haben, in einen einzigen Katalog, gezeichnet als **Models**, der erste Tab der Settings: Ihre Reviewer, die Modelle des Beraters und des Fragen-Beraters (jedes, das sie verschieben kann — siehe unten) und Ihre gespeicherten Chat-Modelle. Eine Berater- oder Fragenzeile nennt danach ein Modell dort, statt Laufzeit, Modell, Endpunkt und CLI-Pfad zu wiederholen, und jedes Modell ist auf seiner Karte für das angehakt, wofür es verwendet wird. Eine umgezogene Installation öffnet die Settings auf Models, mit jedem alten Reviewer, Berater und Chat-Modell darauf, und der Umzug selbst ändert keine Runde: coai-mcp führt dieselben Modelle aus wie vorher.",
    why: "Bisher konnte ein Modell dreimal definiert sein — als Reviewer, als Berater und als Zeile des Fragen-Beraters —, und wer eine Kopie änderte, ließ die anderen zurück. Eine Liste, mit einem Häkchen für jede Verwendung, ist die Abhilfe.",
    setup: "Nichts einzurichten. Es läuft einmal beim Start der Erweiterung: für Ihre eigenen Einstellungen und für die eigenen Einstellungen dieser Seite, wenn **separate settings for each side** eingeschaltet ist. Eine Kopie im vorherigen Zustand liegt in `coai.migratedFrom`, und `coai.catalogMigration` hält fest, dass die Einstellungen umgezogen sind. Ihre Chat-Modell-Presets ziehen genauso um: Jedes wird ein eigenes Modell mit Häkchen bei Chat, und `coai.chatPresetsMoved` merkt sich, welche umgezogen sind — ein Chat-Modell, das Sie von Models entfernen, bleibt also entfernt.",
    usage: "Zum Rückgängigmachen führen Sie **ConnectOtherAIs: Restore settings from before the catalog** aus der Befehlspalette aus. Der Befehl nennt die Einstellungen, die er ändert, fragt einmal nach und stellt Reviewer, Berater und Zeilen des Fragen-Beraters genau so wieder her, wie sie waren. Wiederhergestellte Einstellungen werden nicht von selbst erneut verschoben.",
    whatCanGoWrong: "Ein Berater, dessen Name keine gültige Modell-ID ist (Kleinbuchstaben, Ziffern und Bindestriche), bleibt, wo er ist, und eine Meldung nennt ihn. Ein Umzug, der die Liste über 64 Modelle brächte, wird gar nicht ausgeführt, und die Meldung sagt, wie viele er gebraucht hätte. Eine Modelleinstellung in der eigenen `.vscode/settings.json` eines Repositorys wird nie angewendet und nie verschoben: Die Modelle eines Reviews werden nur aus Ihren eigenen Einstellungen gelesen.\n\nEine ältere Version dieser Erweiterung, die die Liste der Modelle speichert, verliert die zusätzlichen Felder der neuen Zeilen; diese Version gibt die benötigten beim nächsten Start zurück. **Zu einer älteren Version zurückzugehen ist kein Rückweg:** sie überschreibt die Einstellungsdatei nicht, die diese Version für coai-mcp gestempelt hat, sodass, was Sie darin bearbeiten, coai-mcp nie erreicht — der Rückweg ist wieder diese Version. Die alten Chat-Vorlagen bleiben, wo sie waren, sodass eine ältere Version sie weiterhin liest, und **Restore settings from before the catalog** stellt die alten Einstellungen wieder her. Die Wiederherstellung ersetzt alles, was sich seit dem Umzug in diesen drei Einstellungen geändert hat.",
  },
  "the-audit-log": {
    title: "Unter der Haube: das Audit-Log",
    whatItIs: "Eine Logdatei pro Serverlauf, unter `logs/<Tag>/` in demselben Ordner, in dem der Server alles andere hält — siehe *Wo Ihre Daten liegen*. Darin die Besetzung jeder Runde, Start und Antwort jedes Reviewers mit Tokens und Geld, jede Absage als Warnung mit Grund, und jeder Befund mit seiner Herkunft.",
    why: "Die Rundenzusammenfassung ist bewusst ein Satz, und ein Satz beantwortet nicht „warum ist dieser Reviewer gescheitert“. Diese Frage kam an einem echten Gate zweimal auf, und beide Male gab es nichts zu antworten.",
    setup: "Nichts einzustellen. Die Stufen kommen aus der Konfiguration statt aus Aufrufstellen, und je Lauf entsteht eine neue Datei — nicht je Tag, weil fast immer gefragt wird, was JENER Lauf getan hat.",
    usage: "Auf Debug-Stufe wird die exakte Kommandozeile jedes Reviewers geschrieben — das ist der Unterschied zwischen „wissen, dass der Hersteller gefragt wurde“ und „den Befehl ins Terminal einfügen und dieselbe Absage sehen“.",
    whatCanGoWrong: "Das Log ist der einzige Ort, an dem manches überhaupt festgehalten wird. Es rotiert nicht und wird nicht beschnitten: ein Jahr dichter Arbeit ist ein Ordner kleiner Dateien — kein Problem, aber aufräumen müssen Sie ihn.",
  },
  "where-your-data-lives": {
    title: "Wo Ihre Daten liegen, und wie Sie sie behalten",
    whatItIs: "Ein Ordner enthält alles, woran sich dieses Produkt erinnert: die Runden-Datenbank, die Sitzungen, Ihre Chats mit ihren Bildern, die von Ihnen bearbeiteten Prompts, das Ausgabenbuch und die Prüfaufzeichnungen. Standardmäßig ist das `%LOCALAPPDATA%\\coai-mcp` unter Windows und `~/.local/share/coai-mcp` sonst. Der Tab **Setup › MCP server** der Settings nennt den Ordner, den genau dieses Fenster liest.",
    why: "Der Standardordner liegt auf der Systemplatte, und die Systemplatte ist das, was formatiert wird. Zeigen Sie stattdessen auf ein Netzlaufwerk oder ein NAS, und Ihre Historie überlebt das Betriebssystem darüber: neu installieren, den MCP-Server erneut einrichten, denselben Ordner wählen — und jede Runde, die Sie je gefahren haben, ist noch da. Denselben Ordner können sich ein Windows-Fenster und ein WSL-Fenster derselben Maschine teilen.",
    setup: "Die Installation des MCP-Servers fragt, beim ersten Mal auf jeder Seite einer Maschine: den Standardordner behalten oder einen wählen. Einen Ordner zu wählen, in dem bereits eine Datenbank liegt, ÜBERNIMMT sie — genau darum geht es, und so nimmt eine neu aufgesetzte Maschine ihre eigene Historie wieder auf. Sie können es auch selbst in den Einstellungen setzen: `coai.dataDirectory` für den Ordner und `coai.dataSide` für den Namen dieser Installation darin. Beide werden pro Seite der Maschine gehalten, denn dasselbe NAS ist `Z:\\coai` in einem Windows-Fenster und `/mnt/z/coai` in einem WSL-Fenster. Danach trägt der Tab **Setup › MCP server** der Settings **Change where your data lives…** und **Move what is here to another folder…**, und die Befehlspalette hat dieselben zwei Einträge.",
    usage: "Ein Server erfährt den Ordner nur aus dem Client-Eintrag, der ihn startet; deshalb trägt der Block, den *Install the MCP server…* in Ihre Zwischenablage legt, ihn bereits mit: einmal einfügen, den Assistenten neu starten — und beide Hälften lesen dieselbe Stelle.\n\nGeben Sie einer Seite einen Namen, wenn sich zwei Installationen einen Ordner teilen; jede hält darin ihre eigene Datenbank, ihre Sitzungen und ihre Anmeldungen. Lassen Sie ihn leer, wenn nur diese Installation den Ordner benutzt.",
    whatCanGoWrong: "Panel und Server können am Ende verschiedene Ordner lesen — genau das bedeutet eine leere Rundenliste, während Ihr Assistent sagt, er prüfe gerade. Der Tab MCP server nennt den Ordner, den DIESES FENSTER liest, und reicht die zwei Zeilen heraus, mit denen ein Server ihm zustimmt.\n\nEin Seitenname darf Kleinbuchstaben, Ziffern, Punkt, Bindestrich und Unterstrich enthalten. Alles andere wird zurückgewiesen statt stillschweigend ignoriert, und der Server startet damit nicht: ein Rückfall auf den gemeinsamen Ordner setzte jede Installation auf eine Datenbank — das Gegenteil dessen, wofür eine Seite da ist.\n\nEinen Ordner umzuziehen, in dem schon etwas liegt, ist eine Kopie, die Sie machen, während nichts läuft, und es ist mehr als die Datenbank: die Sitzungen, die Chats und ihre Bücher, die bearbeiteten Prompts, das Ausgabenbuch und die Prüfaufzeichnungen und die Logs ziehen mit um — mit einer Ausnahme: haben Sie dieser Installation einen Seitennamen gegeben, schreibt der Server seine Logs in den Ordner ÜBER der Seite, sodass ein Umzug sie nicht erreicht und das vorher sagt. Lassen Sie die flüchtigen Worktrees und die Anmelde-Token zurück — ein Token gehört der Seite, die ihn erworben hat.\n\n**Move your data to another folder** — die Schaltfläche **Move what is here to another folder…** im selben Tab — erledigt diese Kopie für Sie: es verweigert, solange noch etwas schreibt, verweigert einen Ordner, der bereits eine eigene Historie hält, kopiert, und liest den neuen Ordner dann zurück und vergleicht ihn mit dem alten, bevor es dieses Fenster dorthin zeigen lässt. Es löscht nichts. **Delete the old data folder** ist eine eigene Aktion und bleibt verweigert, bis ein Umzug aufgegangen ist — eine Kopie, die nicht aufging, ist eine, für die der alte Ordner die einzige Stelle sein kann, an der etwas noch existiert.",
  },
};
